/// Where a native `Int` result's Rust shape is decided. A Core row's shape is
/// the registry's raw-machine-word fact; a native host slot (record field,
/// enum payload, Prelude route) is chosen by its declared Rust type.
#[derive(Clone, Copy, PartialEq, Eq)]
enum NativeIntSource {
    MachineWord,
    DeclaredSlot,
}
/// Prelude kernels whose listed argument positions take the owned exact
/// `Int` carrier rather than a raw machine word. Every engine that lowers a
/// Core call reads this one table; a row named here is never narrowed.
pub fn exact_prelude_adapter(bare: &str) -> Option<(&'static str, &'static [usize])> {
        Some(match bare {
            "jet_fraction_from_parts" => ("jet_fraction_from_owned_parts", &[0, 1]),
            "jet_fraction_numerator" => ("jet_fraction_owned_numerator", &[]),
            "jet_fraction_denominator" => ("jet_fraction_owned_denominator", &[]),
            "JetDate::new" => ("jet_local_date_owned", &[0, 1, 2]),
            "JetLocalTime::new" => ("jet_local_time_owned", &[0, 1, 2]),
            "JetPeriod::new" => ("jet_period_owned", &[0, 1, 2]),
            "jet_std::jet_int_abs" => ("jet_std::jet_int_owned_abs", &[0]),
            "jet_std::jet_int_add" => ("jet_std::jet_int_owned_add", &[0, 1]),
            "jet_std::jet_int_sub" => ("jet_std::jet_int_owned_sub", &[0, 1]),
            "jet_std::jet_int_mul" => ("jet_std::jet_int_owned_mul", &[0, 1]),
            "jet_std::jet_int_bit_and" => ("jet_std::jet_int_owned_bit_and", &[0, 1]),
            "jet_std::jet_int_bit_or" => ("jet_std::jet_int_owned_bit_or", &[0, 1]),
            "jet_std::jet_int_bit_xor" => ("jet_std::jet_int_owned_bit_xor", &[0, 1]),
            "jet_std::jet_int_neg" => ("jet_std::jet_int_owned_neg", &[0]),
            "jet_std::jet_int_not" => ("jet_std::jet_int_owned_not", &[0]),
            "jet_std::jet_int_div" => ("jet_std::jet_int_owned_div", &[0, 1]),
            "jet_std::jet_int_rem" => ("jet_std::jet_int_owned_rem", &[0, 1]),
            "jet_std::jet_int_div_euclid" => ("jet_std::jet_int_owned_div_euclid", &[0, 1]),
            "jet_std::jet_int_rem_euclid" => ("jet_std::jet_int_owned_rem_euclid", &[0, 1]),
            "jet_std::jet_int_floor_div" => ("jet_std::jet_int_owned_floor_div", &[0, 1]),
            "jet_std::jet_int_mod" => ("jet_std::jet_int_owned_mod", &[0, 1]),
            "jet_std::jet_int_pow" => ("jet_std::jet_int_owned_pow", &[0, 1]),
            "jet_std::jet_int_shl" => ("jet_std::jet_int_owned_shl", &[0, 1]),
            "jet_std::jet_int_shr" => ("jet_std::jet_int_owned_shr", &[0, 1]),
            "jet_std::jet_int_checked_widen" => ("jet_std::jet_int_owned_checked_widen", &[0]),
            "jet_std::jet_int_try_from_checked" => {
                ("jet_std::jet_int_owned_try_from_checked", &[0])
            }
            "jet_std::jet_int_checked_fixed" => ("jet_std::jet_int_owned_checked_fixed", &[0]),
            "jet_numeric_int_bit_count" => ("jet_std::jet_int_owned_bit_count", &[0]),
            "jet_inline_range_from_int" => ("jet_std::jet_int_owned_inline_range", &[0]),
            "jet_std::jet_int_to_radix" => ("jet_std::jet_int_owned_to_radix", &[0, 1]),
            "jet_std::jet_int_from_radix" => ("jet_std::jet_int_owned_from_radix", &[1]),
            "jet_std::jet_int_parse" => ("jet_std::jet_int_owned_parse", &[]),
            "jet_fmt_decimal_int" => ("jet_std::jet_fmt_decimal_int_owned", &[0, 1]),
            "jet_fmt_grouped_int" => ("jet_std::jet_fmt_grouped_int_owned", &[0, 1]),
            "jet_fmt_hex" => ("jet_std::jet_fmt_hex_owned", &[0, 1]),
            "jet_fmt_bin" => ("jet_std::jet_fmt_bin_owned", &[0]),
            "jet_fmt_oct" => ("jet_std::jet_fmt_oct_owned", &[0]),
            _ => return None,
        })
}
fn quote_rust_string(value: &str) -> String {
    crate::Codegen::escape_rust_str(value)
}

/// The sentry guard for one audited `#Unsafe` gate (D-MEM-SENTRY1). Block
/// scopes, gated function bodies, and gated foreign calls share this spelling.
fn sentry_gate_scope(gate: &jet_foundation::MIR::MirUnsafeGate) -> String {
    let constructor = if gate.fenced {
        "jet_sentry_fenced_scope"
    } else {
        "jet_sentry_scope"
    };
    format!(
        "jet_mem::{constructor}({}, {:?}, {}, {:?})",
        gate.enabled, gate.file, gate.line, gate.reason
    )
}

fn allocator_view_inner(ty: &MirType) -> Option<&MirType> {
    match ty.kind() {
        MirTypeKind::Tagged {
            marker: MirTagMarker::Internal(MirInternalTag::AllocatorView),
            inner,
        } => Some(inner),
        _ => None,
    }
}
/// The MIR nominal the TIR lowering gives a `#Transact` block's Shared STM
/// guard; generated Rust carries it as the root `JetSharedTransaction`.
const STM_TYPE: &str = "Stm";

fn is_shared_guard_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Tagged { inner, .. } => is_shared_guard_type(inner),
        MirTypeKind::Apply { name, .. } => name.name == crate::Syntax::TYPE_SHARED_GUARD,
        _ => false,
    }
}

fn is_allocator_result_type(ty: &MirType) -> bool {
    matches!(
        ty.kind(),
        MirTypeKind::Result { err, .. } if err.name().starts_with("AllocError")
    )
}

fn is_string_view_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Apply { name, args }
            if matches!(name.name.as_str(), "View" | "ViewMut") && args.len() == 1 =>
        {
            matches!(
                args[0].kind(),
                MirTypeKind::Apply { name, args }
                    if args.is_empty() && name.name == "str"
            )
        }
        MirTypeKind::Tagged { inner, .. } => is_string_view_type(inner),
        _ => false,
    }
}

fn is_view_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Apply { name, .. } if matches!(name.name.as_str(), "View" | "ViewMut") => true,
        MirTypeKind::Tagged { inner, .. } => is_view_type(inner),
        _ => false,
    }
}

/// These carriers are native references, not owners of their referents.
/// Reading them at scope cleanup would extend a borrow past its checked last use.
fn is_nonowning_reference_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Tagged {
            marker: MirTagMarker::Internal(MirInternalTag::AllocatorView),
            ..
        } => true,
        MirTypeKind::Tagged { inner, .. } => is_nonowning_reference_type(inner),
        MirTypeKind::Apply { name, args } => {
            args.len() == 1 && matches!(name.name.as_str(), "View" | "ViewMut" | "Pin")
        }
        _ => false,
    }
}

/// D-PIN1=A: `Pin<T>`, the exclusive reference to a pinned place.
fn is_pin_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Tagged { inner, .. } => is_pin_type(inner),
        MirTypeKind::Apply { name, args } => {
            args.len() == 1 && name.name == jet_foundation::Syntax::TYPE_PIN
        }
        _ => false,
    }
}

/// True when `ty` carries a `View`/`ViewMut` whose Rust spelling borrows,
/// directly or through a nominal type `carrier` reports as holding one.
fn type_contains_view(ty: &MirType, carrier: &dyn Fn(&str) -> bool) -> bool {
    let nested = |inner: &MirType| type_contains_view(inner, carrier);
    match ty.kind() {
        MirTypeKind::Apply { name, args } => {
            // D-PIN1=A: `Pin<T>` joins the borrowed-window family (`&mut T`).
            (matches!(name.name.as_str(), "View" | "ViewMut" | "Pin") && args.len() == 1)
                || carrier(&name.name)
                || args.iter().any(nested)
        }
        MirTypeKind::List(inner) | MirTypeKind::Shared(inner) | MirTypeKind::Option(inner) => {
            nested(inner)
        }
        MirTypeKind::Map { key, value } => nested(key) || nested(value),
        MirTypeKind::Result { ok, err } => nested(ok) || nested(err),
        MirTypeKind::Tuple(fields) => fields.iter().any(|(_, field)| nested(field)),
        MirTypeKind::FixedList { elem, .. } => nested(elem),
        MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => nested(inner),
        MirTypeKind::Union(members) => members.iter().any(nested),
        _ => false,
    }
}

/// D-MEM-VIEWRET1 (#4392): the names and keys of every Jet-declared type
/// whose stored data holds a view, so its Rust declaration takes the
/// `'__jet_view` lifetime parameter and every use names one. A type holding
/// such a type holds one too; the set grows to its fixed point. Rows the
/// runtime or Prelude spell (`declared` false) keep their own Rust type.
fn collect_view_carriers(
    program: &MirProgram,
    declared: &dyn Fn(&MirTypeDef) -> bool,
) -> BTreeSet<String> {
    let mut carriers = BTreeSet::new();
    loop {
        let mut grew = false;
        for def in &program.types {
            if carriers.contains(&def.key) || !declared(def) {
                continue;
            }
            let carrier = |name: &str| carriers.contains(name);
            let holds = |ty: &MirType| type_contains_view(ty, &carrier);
            let carries = match &def.kind {
                MirTypeDefKind::Struct { fields, .. } => fields
                    .iter()
                    .filter(|field| !field.computed)
                    .any(|field| holds(&field.ty)),
                MirTypeDefKind::Enum { variants, .. } => {
                    variants.iter().any(|variant| match &variant.payload {
                        MirVariantPayload::Unit => false,
                        MirVariantPayload::Single(ty) => holds(ty),
                        MirVariantPayload::Named(fields) => {
                            fields.iter().any(|field| holds(&field.ty))
                        }
                    })
                }
                MirTypeDefKind::Distinct { base, .. } => holds(base),
                MirTypeDefKind::Alias { target } => holds(target),
                MirTypeDefKind::UnitFamily { .. } => false,
            };
            if carries {
                carriers.insert(def.key.clone());
                carriers.insert(def.name.clone());
                grew = true;
            }
        }
        if !grew {
            return carriers;
        }
    }
}

/// True when dropping a value of `ty` does nothing but free memory: it is a
/// scalar, a `String`, an owned list/map/option/result/tuple of such values,
/// or a nominal row `plain` reports. Handles, shared counts, views, callables,
/// trait objects and tagged carriers are never plain.
fn type_drop_is_plain(ty: &MirType, plain: &dyn Fn(&str) -> bool) -> bool {
    let nested = |inner: &MirType| type_drop_is_plain(inner, plain);
    match ty.kind() {
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Float32
        | MirTypeKind::Bool
        | MirTypeKind::Char
        | MirTypeKind::String
        | MirTypeKind::IntN { .. } => true,
        MirTypeKind::List(inner) | MirTypeKind::Option(inner) => nested(inner),
        MirTypeKind::FixedList { elem, .. } => nested(elem),
        MirTypeKind::InlineRange { base, .. } | MirTypeKind::Quantity { base, .. } => nested(base),
        MirTypeKind::Map { key, value } => nested(key) && nested(value),
        MirTypeKind::Result { ok, err } => nested(ok) && nested(err),
        MirTypeKind::Tuple(fields) => fields.iter().all(|(_, field)| nested(field)),
        MirTypeKind::Apply { name, args } => args.is_empty() && plain(&name.name),
        _ => false,
    }
}

/// The names and keys of program-declared, non-generic, owned type rows
/// whose values own nothing but memory (`type_drop_is_plain` for every
/// stored field and payload). Rows the runtime spells (`runtime_declared`),
/// compiler builtins, Core rows (`<corelib>/`, `core.`, `core::` keys), view
/// carriers, laid-out rows and shared or move-only rows are never plain, and
/// neither is a name or key any such row also uses. The set starts from every
/// eligible row and shrinks to its fixed point, so recursive rows stay plain.
fn collect_plain_drop_types(
    program: &MirProgram,
    runtime_declared: &dyn Fn(&MirTypeDef) -> bool,
    view_carriers: &BTreeSet<String>,
) -> BTreeSet<String> {
    let eligible = |def: &MirTypeDef| {
        !runtime_declared(def)
            && def.compiler_builtin.is_none()
            && !def.key.starts_with("<corelib>/")
            && !def.key.starts_with("core.")
            && !def.key.starts_with("core::")
            && def.generic_params.is_empty()
            && def.layout.is_none()
            && matches!(def.ownership, MirOwnershipMode::Copy | MirOwnershipMode::Owned)
            && !view_carriers.contains(&def.key)
    };
    let mut plain = BTreeSet::new();
    let mut tainted = BTreeSet::new();
    for def in &program.types {
        let set = if eligible(def) { &mut plain } else { &mut tainted };
        set.insert(def.key.clone());
        set.insert(def.name.clone());
    }
    for label in &tainted {
        plain.remove(label);
    }
    loop {
        let mut shrank = false;
        for def in &program.types {
            if !plain.contains(&def.key) && !plain.contains(&def.name) {
                continue;
            }
            let holds = |ty: &MirType| type_drop_is_plain(ty, &|name: &str| plain.contains(name));
            let stays = match &def.kind {
                MirTypeDefKind::Struct { fields, .. } => fields
                    .iter()
                    .filter(|field| !field.computed)
                    .all(|field| holds(&field.ty)),
                MirTypeDefKind::Enum { variants, .. } => {
                    variants.iter().all(|variant| match &variant.payload {
                        MirVariantPayload::Unit => true,
                        MirVariantPayload::Single(ty) => holds(ty),
                        MirVariantPayload::Named(fields) => fields.iter().all(|field| holds(&field.ty)),
                    })
                }
                MirTypeDefKind::Distinct { base, .. } => holds(base),
                MirTypeDefKind::Alias { target } => holds(target),
                MirTypeDefKind::UnitFamily { .. } => true,
            };
            if !stays {
                plain.remove(&def.key);
                plain.remove(&def.name);
                shrank = true;
            }
        }
        if !shrank {
            return plain;
        }
    }
}

/// D-MEM-VIEWRET1 (#4392): the lifetime a callable signature names for the
/// views it returns.
enum ViewReturnLifetime {
    /// No returned view, or Rust elision already ties it to its one owner.
    Elided,
    /// Every owner is a static.
    Static,
    /// `'__jet_view`, carried by the receiver and/or these declared parameters.
    Named { receiver: bool, params: BTreeSet<usize> },
}

const VIEW_RETURN_LIFETIME: &str = "'__jet_view";

fn view_owner_borrow(rendered: String, carries_view: bool) -> String {
    if let Some(rest) = rendered.strip_prefix("&mut ") {
        if carries_view {
            rendered
        } else {
            format!("&{VIEW_RETURN_LIFETIME} mut {rest}")
        }
    } else if rendered.starts_with("&'")
        || rendered
            .strip_prefix("&&'")
            .and_then(|inner| inner.split_once(' '))
            .is_some_and(|(_, pointee)| !pointee.starts_with("mut "))
    {
        rendered
    } else if let Some(rest) = rendered.strip_prefix('&') {
        format!("&{VIEW_RETURN_LIFETIME} {rest}")
    } else {
        rendered
    }
}

/// The higher-ranked lifetime a callable type names when its returned view
/// borrows from its own arguments.
const CALLABLE_VIEW_LIFETIME: &str = "'__jet_fn";

/// `<lifetimes…, generics…>` for a signature whose type generics render as
/// `generics` (`""` or `<…>`).
fn signature_generics(lifetimes: &[&str], generics: &str) -> String {
    if lifetimes.is_empty() {
        return generics.to_string();
    }
    let lifetimes = lifetimes.join(", ");
    match generics.strip_prefix('<') {
        Some(rest) => format!("<{lifetimes}, {rest}"),
        None => format!("<{lifetimes}>"),
    }
}
/// Formatting-only policy for the MIR Rust adapter.
///
/// All semantic choices are MIR facts.  The adapter may choose the generated
/// module root and whether item classes are included in this fragment, but it
/// cannot provide a semantic or symbol lookup table.
#[derive(Debug, Clone)]
pub struct MirRustConfig<'a> {
    pub target: TargetLayout,
    pub target_kind: MirRustTarget,
    pub root_prefix: String,
    pub execution: MirRustExecutionConfig<'a>,
}
/// Exact Rust-facing identity and type metadata for the ordinary AOT artifact.
///
/// This is an integration descriptor, not a second symbol or type resolver.
/// Every string is produced by the same `RustEmitter` methods that emit the
/// corresponding item.  Private source-coupled host glue may use it to bind a
/// generated callable without guessing mangled names or assigning an
/// incompatible Rust function pointer.
#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustCallableMetadata {
    pub function: MirFunctionId,
    pub symbol: String,
    pub parameter_types: Vec<String>,
    pub parameter_access: Vec<MirAccess>,
    pub return_type: String,
    pub callable_type: String,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustTypeMetadata {
    pub ty: MirTypeId,
    pub symbol: String,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustFieldMetadata {
    pub field: MirFieldId,
    pub owner: MirTypeId,
    pub symbol: String,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustVariantMetadata {
    pub owner: MirTypeId,
    pub source_name: String,
    pub wire_name: String,
    pub symbol: String,
    pub payload_types: Vec<String>,
}
#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustTraitMetadata {
    pub trait_id: MirTraitId,
    pub key: String,
    pub name: String,
    pub symbol: String,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirRustTraitMethodMetadata {
    pub trait_id: MirTraitId,
    pub method_id: MirTraitMethodId,
    pub key: String,
    pub name: String,
    pub symbol: String,
    pub receiver_access: Option<MirAccess>,
    pub parameter_types: Vec<String>,
    pub parameter_access: Vec<MirAccess>,
    pub return_type: String,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct MirRustAotMetadata {
    pub callables: Vec<MirRustCallableMetadata>,
    pub types: Vec<MirRustTypeMetadata>,
    pub fields: Vec<MirRustFieldMetadata>,
    pub variants: Vec<MirRustVariantMetadata>,
    pub traits: Vec<MirRustTraitMetadata>,
    pub trait_methods: Vec<MirRustTraitMethodMetadata>,
}


#[derive(Debug, Clone)]
pub struct MirRustExecutionConfig<'a> {
    /// The checked artifact plan whose rows this adapter is allowed to emit.
    pub artifact: MirArtifactId,
    /// Prepared physical bridge binding; language checks remain canonical MIR facts.
    pub ffi: Option<&'a crate::AST::FfiLink>,
    pub emit_types: bool,
    pub emit_foreign: bool,
    pub emit_metadata: bool,
    pub semantic_digest: Option<[u8; 32]>,
    pub emit_debug_linemap: bool,
    /// Include the complete cached Prelude/Core runtime in this artifact.
    ///
    /// Standalone MIR emission keeps this enabled. An enclosing target
    /// assembler may disable it only when that assembler supplies the same
    /// complete runtime closure.
    pub emit_runtime: bool,
    /// D-DX-PROD1: one typed release policy controls every emitted DevTools
    /// producer.  The code generator never reconstructs a parallel bool.
    pub release_devtools_policy: jet_pkg_model::Package::ReleaseDevtoolsPolicy,
}

impl<'a> MirRustExecutionConfig<'a> {
    pub fn for_artifact(artifact: MirArtifactId) -> Self {
        Self {
            artifact,
            ffi: None,
            emit_types: true,
            emit_foreign: true,
            emit_metadata: false,
            semantic_digest: None,
            emit_debug_linemap: false,
            emit_runtime: true,
            release_devtools_policy: jet_pkg_model::Package::ReleaseDevtoolsPolicy::development(),
        }
    }
}

/// Calls `found` with the trait name of every single-bound trait object
/// (`Box<dyn T>`) inside `ty`.
fn mir_type_single_trait_objects(ty: &MirType, found: &mut impl FnMut(&str)) {
    match ty.kind() {
        MirTypeKind::TraitObject(bounds) => {
            if let [bound] = bounds.as_slice() {
                found(&bound.name);
            }
        }
        MirTypeKind::Apply { args: inner, .. } | MirTypeKind::Union(inner) => {
            for ty in inner {
                mir_type_single_trait_objects(ty, found);
            }
        }
        MirTypeKind::List(inner)
        | MirTypeKind::Shared(inner)
        | MirTypeKind::Option(inner)
        | MirTypeKind::FixedList { elem: inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => mir_type_single_trait_objects(inner, found),
        MirTypeKind::Map { key, value }
        | MirTypeKind::Result { ok: key, err: value } => {
            mir_type_single_trait_objects(key, found);
            mir_type_single_trait_objects(value, found);
        }
        MirTypeKind::Tuple(fields) => {
            for (_, field) in fields {
                mir_type_single_trait_objects(field, found);
            }
        }
        MirTypeKind::Fn(signature) => {
            for param in &signature.params {
                mir_type_single_trait_objects(param, found);
            }
            if let Some(ret) = signature.ret.as_deref() {
                mir_type_single_trait_objects(ret, found);
            }
        }
        MirTypeKind::SendFn { params, ret, .. } => {
            for param in params {
                mir_type_single_trait_objects(param, found);
            }
            if let Some(ret) = ret.as_deref() {
                mir_type_single_trait_objects(ret, found);
            }
        }
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Bool
        | MirTypeKind::String
        | MirTypeKind::Char
        | MirTypeKind::IntN { .. }
        | MirTypeKind::Float32
        | MirTypeKind::Measure(_) => {}
    }
}

/// Runtime symbol families whose generic parameters carry codec bounds.
/// Mirrored by JetFoundation's MIR reachability classification.
const CODEC_ROUTE_PREFIXES: [&str; 16] = [
    "jet_codec_", "jet_decode_", "jet_enc_", "jet_data_", "jet_db_",
    "jet_args_", "jet_config_", "jet_std_env_", "jet_http_", "jet_job_",
    "jet_receipt_", "jet_sync_", "jet_app_", "jet_web_", "jet_testing_",
    "jet_history_",
];
const CODEC_ROUTE_LEAVES: [&str; 7] = [
    "call", "decode", "from_json", "loader", "snapshot", "register_type", "typed_factory",
];

/// Whether a runtime route may require codecs at its instantiated types.
fn codec_route_symbol(symbol: &str) -> bool {
    let leaf = symbol.rsplit([':', '.']).next().unwrap_or(symbol);
    CODEC_ROUTE_PREFIXES.iter().any(|prefix| leaf.starts_with(prefix))
        || CODEC_ROUTE_LEAVES.contains(&leaf)
}

/// The serde codecs (`[Encode, Decode]`) a trait bound list requires.
fn mir_bound_codecs(bounds: &[MirTraitRef]) -> [bool; 2] {
    let mut codecs = [false, false];
    for bound in bounds {
        let leaf = bound.name.rsplit(['.', ':']).next().unwrap_or(&bound.name);
        codecs[0] |= leaf == crate::Generics::ENCODE || leaf == jet_foundation::Syntax::MARKER_CODABLE;
        codecs[1] |= leaf == crate::Generics::DECODE || leaf == jet_foundation::Syntax::MARKER_CODABLE;
    }
    codecs
}

/// Every nominal type name inside `ty`, including type arguments and
/// collection elements.
fn mir_type_nominals<'p>(ty: &'p MirType, names: &mut Vec<&'p str>) {
    match ty.kind() {
        MirTypeKind::Apply { name, args } => {
            names.push(name.name.as_str());
            for arg in args {
                mir_type_nominals(arg, names);
            }
        }
        MirTypeKind::TraitObject(bounds) => {
            names.extend(bounds.iter().map(|bound| bound.name.as_str()));
        }
        MirTypeKind::List(inner)
        | MirTypeKind::Shared(inner)
        | MirTypeKind::Option(inner)
        | MirTypeKind::FixedList { elem: inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => mir_type_nominals(inner, names),
        MirTypeKind::Map { key, value }
        | MirTypeKind::Result {
            ok: key,
            err: value,
        } => {
            mir_type_nominals(key, names);
            mir_type_nominals(value, names);
        }
        MirTypeKind::Tuple(fields) => {
            for (_, field) in fields {
                mir_type_nominals(field, names);
            }
        }
        MirTypeKind::Union(members) => {
            for member in members {
                mir_type_nominals(member, names);
            }
        }
        MirTypeKind::Fn(signature) => {
            for param in &signature.params {
                mir_type_nominals(param, names);
            }
            if let Some(ret) = signature.ret.as_deref() {
                mir_type_nominals(ret, names);
            }
        }
        MirTypeKind::SendFn { params, ret, .. } => {
            for param in params {
                mir_type_nominals(param, names);
            }
            if let Some(ret) = ret.as_deref() {
                mir_type_nominals(ret, names);
            }
        }
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Bool
        | MirTypeKind::String
        | MirTypeKind::Char
        | MirTypeKind::IntN { .. }
        | MirTypeKind::Float32
        | MirTypeKind::Measure(_) => {}
    }
}

/// Rust rejects an alias parameter its target never names (E0091), while a
/// transparent Jet alias may ignore an argument (`alias P<T> :: Point`). The
/// Rust alias keeps only the parameters its target names; references drop the
/// arguments at the same positions. `None` for every non-alias row.
fn alias_parameter_uses(def: &MirTypeDef) -> Option<Vec<bool>> {
    let MirTypeDefKind::Alias { target } = &def.kind else {
        return None;
    };
    let mut names = Vec::new();
    mir_type_nominals(target, &mut names);
    Some(
        def.generic_params
            .iter()
            .map(|param| names.contains(&param.name.as_str()))
            .collect(),
    )
}


/// Which `program.impls` rows to emit when stage zero prunes codecs. The
/// candidates are derived serde impls (`compiler_generated` with a codec) on
/// a nominal type; every other function is a root. A scanned body demands a
/// candidate by calling one of its methods, or by naming its nominal type
/// anywhere inside a call's type arguments: generic Prelude codecs such as
/// `jet_codec_decode_typed::<[T]>` reach the impl through Rust trait bounds.
/// A demanded impl's methods are scanned in turn. A missed demand fails
/// rustc with E0277; it never changes behavior.
fn demanded_codec_impls(program: &MirProgram) -> Vec<bool> {
    let candidate = |implementation: &MirImplDef| {
        implementation.compiler_generated
            && implementation.serde.is_some()
            && implementation.self_type.nominal_name().is_some()
    };
    let mut keep = program
        .impls
        .iter()
        .map(|implementation| !candidate(implementation))
        .collect::<Vec<_>>();
    let mut by_method = BTreeMap::<MirFunctionId, usize>::new();
    // Per codec (`[Encode, Decode]`): candidate rows by self nominal.
    let mut by_name = [
        HashMap::<&str, Vec<usize>>::new(),
        HashMap::<&str, Vec<usize>>::new(),
    ];
    for (index, implementation) in program.impls.iter().enumerate() {
        if keep[index] {
            continue;
        }
        for method in &implementation.methods {
            by_method.insert(*method, index);
        }
        if let Some(name) = implementation.self_type.nominal_name() {
            let codec = usize::from(implementation.serde == Some(MirSerdeCodec::Decode));
            by_name[codec].entry(name).or_default().push(index);
        }
    }
    let functions = program
        .functions
        .iter()
        .map(|function| (function.id, function))
        .collect::<BTreeMap<_, _>>();
    let prelude_codec_routes = program
        .prelude_calls
        .iter()
        .filter(|call| match &call.symbol {
            MirSymbol::Prelude(symbol) | MirSymbol::Runtime(symbol) => codec_route_symbol(symbol),
        })
        .map(|call| call.id)
        .collect::<HashSet<_>>();
    let core_codec_calls = program
        .core_calls
        .iter()
        .filter(|call| codec_route_symbol(call.symbol.name()))
        .map(|call| call.id)
        .collect::<HashSet<_>>();
    let mut demands = CodecDemands::default();
    for job in &program.jobs {
        if let Some(&function) = functions.get(&job.function) {
            mir_signature_codec_roots(function, &mut |ty| demands.ty(BOTH_CODECS, ty));
        }
    }
    for export in program.artifacts.iter().flat_map(|artifact| &artifact.exports) {
        if let Some(&function) = functions.get(&export.function) {
            mir_signature_codec_roots(function, &mut |ty| demands.ty(BOTH_CODECS, ty));
        }
    }
    let mut pending = program
        .functions
        .iter()
        .filter(|function| !by_method.contains_key(&function.id))
        .collect::<Vec<_>>();
    let mut seen_names = [HashSet::<&str>::new(), HashSet::<&str>::new()];
    let mut demanded = Vec::new();
    loop {
        for (codec, codec_names) in demands.names.iter_mut().enumerate() {
            for name in codec_names.drain(..) {
                if seen_names[codec].insert(name) {
                    demanded.extend(by_name[codec].get(name).into_iter().flatten().copied());
                }
            }
        }
        for index in demanded.drain(..) {
            if !keep[index] {
                keep[index] = true;
                pending.extend(
                    program.impls[index]
                        .methods
                        .iter()
                        .filter_map(|method| functions.get(method).copied()),
                );
            }
        }
        let Some(function) = pending.pop() else {
            break;
        };
        for instruction in function.blocks.iter().flat_map(|block| &block.instructions) {
            match &instruction.operation {
                MirOperation::Call {
                    callee:
                        callee @ (MirCallee::User(id)
                        | MirCallee::Associated { function: id, .. }
                        | MirCallee::Method { function: id, .. }),
                    type_args,
                    ..
                } => {
                    if let Some(&index) = by_method.get(id) {
                        demanded.push(index);
                    }
                    let codecs = functions.get(id).map_or([false, false], |callee| {
                        callee.generic_params.iter().fold([false, false], |codecs, param| {
                            let bound = mir_bound_codecs(&param.bounds);
                            [codecs[0] | bound[0], codecs[1] | bound[1]]
                        })
                    });
                    if codecs != [false, false] {
                        if let MirCallee::Associated { owner, .. } | MirCallee::Method { owner, .. } =
                            callee
                        {
                            demands.ty(codecs, owner);
                        }
                        demands.instantiated(codecs, function, instruction, type_args);
                    }
                }
                MirOperation::Call {
                    callee: MirCallee::Core(id),
                    type_args,
                    ..
                } if core_codec_calls.contains(id) => {
                    demands.instantiated(BOTH_CODECS, function, instruction, type_args);
                }
                MirOperation::Call {
                    callee: MirCallee::Prelude(id),
                    type_args,
                    ..
                } if prelude_codec_routes.contains(id) => {
                    demands.instantiated(BOTH_CODECS, function, instruction, type_args);
                }
                MirOperation::CoreCall {
                    call,
                    route,
                    type_args,
                    ..
                } if core_codec_calls.contains(call) || prelude_codec_routes.contains(route) => {
                    demands.instantiated(BOTH_CODECS, function, instruction, type_args);
                }
                MirOperation::Call { type_args, .. }
                | MirOperation::CoreCall { type_args, .. }
                | MirOperation::IndirectCall { type_args, .. } => {
                    type_args.iter().for_each(|ty| demands.ty(BOTH_CODECS, ty));
                }
                MirOperation::Semantic(operation)
                    if operation
                        .prelude_calls()
                        .iter()
                        .any(|call| prelude_codec_routes.contains(call)) =>
                {
                    if let MirSemanticOp::StaticPreludeCall {
                        owner_type_args, ..
                    } = operation
                    {
                        for type_arg in owner_type_args {
                            if let MirPreludeTypeArg::Type(ty) = type_arg {
                                demands.ty(BOTH_CODECS, ty);
                            }
                        }
                    }
                    let type_args = match operation {
                        MirSemanticOp::StaticPreludeCall { type_args, .. } => type_args.as_slice(),
                        _ => &[],
                    };
                    demands.instantiated(BOTH_CODECS, function, instruction, type_args);
                }
                _ => {}
            }
        }
    }
    keep
}

const BOTH_CODECS: [bool; 2] = [true, true];

/// Nominal names demanded per codec (`[Encode, Decode]`) and not yet resolved
/// to candidate impl rows.
#[derive(Default)]
struct CodecDemands<'p> {
    names: [Vec<&'p str>; 2],
}

impl<'p> CodecDemands<'p> {
    /// Demand `codecs` of every nominal inside `ty`.
    fn ty(&mut self, codecs: [bool; 2], ty: &'p MirType) {
        let mut found = Vec::new();
        mir_type_nominals(ty, &mut found);
        for (codec, wanted) in codecs.into_iter().enumerate() {
            if wanted {
                self.names[codec].extend(found.iter().copied());
            }
        }
    }

    /// A codec-bounded call instantiated by its type arguments, its operands
    /// (a runtime generic infers its parameter from them) and its result (a
    /// decode returns the parameter).
    fn instantiated(
        &mut self,
        codecs: [bool; 2],
        function: &'p MirFunction,
        instruction: &'p MirInstruction,
        type_args: &'p [MirType],
    ) {
        for ty in type_args {
            self.ty(codecs, ty);
        }
        for value in instruction.operation.value_uses() {
            if let Some((_, ty, ..)) = function.values.iter().find(|(id, ..)| *id == value) {
                self.ty(codecs, ty);
            }
        }
        if let Some(ty) = &instruction.ty {
            self.ty(codecs, ty);
        }
    }
}

/// Every type an export or job wrapper decodes or encodes: its parameters,
/// its result and its failure carrier.
fn mir_signature_codec_roots<'p>(function: &'p MirFunction, found: &mut impl FnMut(&'p MirType)) {
    for param in &function.params {
        found(&param.ty);
    }
    found(&function.return_type);
    match &function.failure {
        MirFailureCarrier::Infallible => {}
        MirFailureCarrier::Result { success, error } => {
            found(success);
            found(error);
        }
        MirFailureCarrier::Optional { value } | MirFailureCarrier::Diverges { value } => found(value),
    }
}

fn mir_type_uses_atomic_word(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Apply { name, args } => {
            name.name == "Atomic"
                || name.name.ends_with("::Atomic")
                || args.iter().any(mir_type_uses_atomic_word)
        }
        MirTypeKind::List(inner)
        | MirTypeKind::Shared(inner)
        | MirTypeKind::Option(inner)
        | MirTypeKind::FixedList { elem: inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => mir_type_uses_atomic_word(inner),
        MirTypeKind::Map { key, value }
        | MirTypeKind::Result {
            ok: key,
            err: value,
        } => mir_type_uses_atomic_word(key) || mir_type_uses_atomic_word(value),
        MirTypeKind::Fn(signature) => {
            signature.params.iter().any(mir_type_uses_atomic_word)
                || signature
                    .ret
                    .as_deref()
                    .is_some_and(mir_type_uses_atomic_word)
        }
        MirTypeKind::SendFn { params, ret, .. } => {
            params.iter().any(mir_type_uses_atomic_word)
                || ret.as_deref().is_some_and(mir_type_uses_atomic_word)
        }
        MirTypeKind::Tuple(fields) => fields
            .iter()
            .any(|(_, field)| mir_type_uses_atomic_word(field)),
        MirTypeKind::Union(members) => members.iter().any(mir_type_uses_atomic_word),
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Bool
        | MirTypeKind::String
        | MirTypeKind::Char
        | MirTypeKind::TraitObject(_)
        | MirTypeKind::IntN { .. }
        | MirTypeKind::Float32
        | MirTypeKind::Measure(_) => false,
    }
}
/// A nominal scalar carrier is emitted inline and does not inherit the
/// structural Rust derives of its surrounding record.  Keep this layout-led:
/// sema already checked the ABI, so the emitter need not recognize a source
/// declaration by name.
fn mir_type_has_inline_nominal_word(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Apply { args, .. } => {
            (matches!(ty.layout.abi, MirAbi::Scalar(_))
                && matches!(ty.layout.size, MirSize::Static(8)))
                || args.iter().any(mir_type_has_inline_nominal_word)
        }
        MirTypeKind::List(inner)
        | MirTypeKind::Shared(inner)
        | MirTypeKind::Option(inner)
        | MirTypeKind::FixedList { elem: inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => mir_type_has_inline_nominal_word(inner),
        MirTypeKind::Map { key, value }
        | MirTypeKind::Result {
            ok: key,
            err: value,
        } => mir_type_has_inline_nominal_word(key) || mir_type_has_inline_nominal_word(value),
        MirTypeKind::Fn(signature) => {
            signature
                .params
                .iter()
                .any(mir_type_has_inline_nominal_word)
                || signature
                    .ret
                    .as_deref()
                    .is_some_and(mir_type_has_inline_nominal_word)
        }
        MirTypeKind::SendFn { params, ret, .. } => {
            params.iter().any(mir_type_has_inline_nominal_word)
                || ret.as_deref().is_some_and(mir_type_has_inline_nominal_word)
        }
        MirTypeKind::Tuple(fields) => fields
            .iter()
            .any(|(_, field)| mir_type_has_inline_nominal_word(field)),
        MirTypeKind::Union(members) => members.iter().any(mir_type_has_inline_nominal_word),
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Bool
        | MirTypeKind::String
        | MirTypeKind::Char
        | MirTypeKind::TraitObject(_)
        | MirTypeKind::IntN { .. }
        | MirTypeKind::Float32
        | MirTypeKind::Measure(_) => false,
    }
}

fn mir_program_uses_atomic_word(program: &MirProgram) -> bool {
    program.type_instances.iter().any(mir_type_uses_atomic_word)
}

fn mir_type_uses_shared_kernel(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::Apply { name, args } => {
            matches!(name.name.as_str(), "Pool" | "ID" | "Shared")
                || args.iter().any(mir_type_uses_shared_kernel)
        }
        MirTypeKind::List(inner)
        | MirTypeKind::Shared(inner)
        | MirTypeKind::Option(inner)
        | MirTypeKind::FixedList { elem: inner, .. }
        | MirTypeKind::InlineRange { base: inner, .. }
        | MirTypeKind::Tagged { inner, .. }
        | MirTypeKind::Quantity { base: inner, .. } => mir_type_uses_shared_kernel(inner),
        MirTypeKind::Map { key, value }
        | MirTypeKind::Result {
            ok: key,
            err: value,
        } => mir_type_uses_shared_kernel(key) || mir_type_uses_shared_kernel(value),
        MirTypeKind::Fn(signature) => {
            signature.params.iter().any(mir_type_uses_shared_kernel)
                || signature
                    .ret
                    .as_deref()
                    .is_some_and(mir_type_uses_shared_kernel)
        }
        MirTypeKind::SendFn { params, ret, .. } => {
            params.iter().any(mir_type_uses_shared_kernel)
                || ret.as_deref().is_some_and(mir_type_uses_shared_kernel)
        }
        MirTypeKind::Tuple(fields) => fields
            .iter()
            .any(|(_, field)| mir_type_uses_shared_kernel(field)),
        MirTypeKind::Union(members) => members.iter().any(mir_type_uses_shared_kernel),
        MirTypeKind::Int
        | MirTypeKind::Float
        | MirTypeKind::Bool
        | MirTypeKind::String
        | MirTypeKind::Char
        | MirTypeKind::TraitObject(_)
        | MirTypeKind::IntN { .. }
        | MirTypeKind::Float32
        | MirTypeKind::Measure(_) => false,
    }
}

fn mir_program_uses_shared_kernel(program: &MirProgram) -> bool {
    program
        .type_instances
        .iter()
        .any(mir_type_uses_shared_kernel)
        || program.prelude_calls.iter().any(|call| {
            let symbol = match &call.symbol {
                MirSymbol::Prelude(symbol) | MirSymbol::Runtime(symbol) => symbol.as_str(),
            };
            symbol.starts_with("jet_shared_")
        })
}

fn mir_program_uses_arrow(program: &MirProgram) -> bool {
    // `core_calls` is the static ABI registry, not the set of calls reached
    // by this package. Reachability is carried through checked package facts.
    program.facts.uses_arrow
}

/// Emit a complete Rust fragment from optimized canonical MIR.
pub fn emit_mir_program(program: &MirProgram, config: &MirRustConfig) -> String {
    let mut out = String::new();
    emit_mir_program_into(program, config, &mut out);
    jet_foundation::WorkCounters::add(jet_foundation::WorkCounters::Work::FunctionsEmitted, program.functions.len());
    jet_foundation::WorkCounters::add(jet_foundation::WorkCounters::Work::EmittedBytes, out.len());
    out
}

/// Describe the exact ordinary-AOT names and carriers emitted for a checked
/// MIR artifact.  Callers that bind private source-coupled host glue must use
/// this descriptor instead of reconstructing symbols from source names.
#[doc(hidden)]
pub fn mir_rust_aot_metadata(
    program: &MirProgram,
    config: &MirRustConfig<'_>,
) -> MirRustAotMetadata {
    let artifact_identity = program
        .artifact_identity(config.execution.artifact)
        .unwrap_or_else(|error| {
            panic!("MIR Rust metadata requires canonical artifact identity: {error}")
        });
    let emitter = RustEmitter::new(program, config, artifact_identity);
    let mut metadata = MirRustAotMetadata::default();

    for function in &program.functions {
        if !emitter.module_selected(function.module_id)
            || !emitter.selected_for_target(function)
            || !matches!(&function.form, MirFunctionForm::TopLevel)
        {
            continue;
        }
        let parameters = emitter.declared_params(function);
        let parameter_types = parameters
            .iter()
            .map(|parameter| emitter.parameter_type(parameter))
            .collect::<Vec<_>>();
        let parameter_access = parameters
            .iter()
            .map(|parameter| parameter.access)
            .collect::<Vec<_>>();
        let callable_parameters = parameters
            .iter()
            .map(|parameter| parameter.ty.clone())
            .collect::<Vec<_>>();
        let callable_type = emitter.callable_type(
            &callable_parameters,
            Some(parameter_access.as_slice()),
            Some(&function.return_type),
            function.return_view_provenance.as_ref(),
        );
        metadata.callables.push(MirRustCallableMetadata {
            function: function.id,
            symbol: emitter.function_name(function.id),
            parameter_types,
            parameter_access,
            return_type: emitter.rust_type(&function.return_type),
            callable_type,
        });
    }

    if config.execution.emit_types {
        for definition in &program.traits {
            if !emitter.module_selected(definition.module) {
                continue;
            }
            metadata.traits.push(MirRustTraitMetadata {
                trait_id: definition.id,
                key: definition.key.clone(),
                name: definition.name.clone(),
                symbol: emitter.trait_name(definition.id),
            });
            for method in &definition.methods {
                let parameter_types = method
                    .params
                    .iter()
                    .map(|parameter| {
                        emitter.synthetic_rollback_parameter_type(definition, parameter)
                    })
                    .collect::<Vec<_>>();
                let parameter_access = method
                    .params
                    .iter()
                    .map(|parameter| parameter.access)
                    .collect::<Vec<_>>();
                metadata
                    .trait_methods
                    .push(MirRustTraitMethodMetadata {
                        trait_id: definition.id,
                        method_id: method.id,
                        key: emitter.trait_method_key(definition, method),
                        name: method.name.clone(),
                        symbol: emitter.trait_method_symbol(definition, method),
                        receiver_access: method.self_access,
                        parameter_types,
                        parameter_access,
                        return_type: emitter
                            .synthetic_rollback_type(definition, &method.return_type),
                    });
            }
        }
    }

    if config.execution.emit_types {
        for definition in &program.types {
            if !emitter.module_selected(definition.module) {
                continue;
            }
            metadata.types.push(MirRustTypeMetadata {
                ty: definition.id,
                symbol: emitter.type_name(definition.id),
            });
            // Variant rows describe the enums this artifact declares; the
            // runtime's own carriers keep their payload spellings there.
            if !emitter.declares_type_def(definition) {
                continue;
            }
            if let MirTypeDefKind::Enum { variants, .. } = &definition.kind {
                emitter.push_generic_scope(&definition.generic_params);
                for variant in variants {
                    let payload_types = match &variant.payload {
                        MirVariantPayload::Unit => Vec::new(),
                        MirVariantPayload::Single(payload) => {
                            vec![emitter.rust_type(payload)]
                        }
                        MirVariantPayload::Named(fields) => fields
                            .iter()
                            .map(|field| emitter.rust_type(&field.ty))
                            .collect(),
                    };
                    metadata.variants.push(MirRustVariantMetadata {
                        owner: definition.id,
                        source_name: variant.name.clone(),
                        wire_name: variant.wire_name.clone(),
                        symbol: emitter.variant_path(Some(definition.id), &variant.name, true),
                        payload_types,
                    });
                }
                emitter.pop_generic_scope();
            }
        }
    }

    for row in &program.fields {
        let symbol = emitter
            .fields
            .get(&row.id)
            .cloned()
            .unwrap_or_else(|| panic!("MIR field ID {:?} has no emitted field name", row.id));
        metadata.fields.push(MirRustFieldMetadata {
            field: row.id,
            owner: row.owner,
            symbol,
        });
    }
    metadata
}

/// The runtime and Core block for one artifact (gated by
/// `config.execution.emit_runtime`): decided by build facts only, never by user
/// source, so `jet_store::runtime::prepare` links it as the `jet_runtime` rlib.
/// Its Prelude sources' test-only items are left out: generated programs are
/// never built with `--test`, so they would only be written, hashed and parsed.
/// The cache identities (`cached_runtime_fingerprint`, the Core closure
/// fingerprint) hash the Prelude text before this deterministic removal.
fn emit_runtime_block(
    emitter: &RustEmitter<'_>,
    program: &MirProgram,
    config: &MirRustConfig<'_>,
    out: &mut String,
) {
    let mut block = String::new();
    push_runtime_block(emitter, program, config, &mut block);
    out.push_str(&jet_foundation::RustSource::strip_test_items(&block));
}

fn push_runtime_block(
    emitter: &RustEmitter<'_>,
    program: &MirProgram,
    config: &MirRustConfig<'_>,
    out: &mut String,
) {
    if config.execution.emit_runtime {
        if emitter.is_no_os() {
            out.push_str("#![no_std]\n#![no_main]\n");
            super::push_portable_corelib_prelude(out, program, emitter.artifact);
        } else {
            let uses_arrow = mir_program_uses_arrow(program)
                || emitter
                    .artifact
                    .runtime_parts
                    .contains(&MirRuntimePartId::Data);
            let active_os = jet_foundation::OSTarget::OSTarget::parse(&program.facts.active_os)
                .or_else(|| jet_foundation::OSTarget::OSTarget::from_triple(&config.target.triple))
                .unwrap_or_else(jet_foundation::OSTarget::OSTarget::host);
            super::push_cached_runtime_begin_with_policy(
                out,
                config.execution.ffi,
                uses_arrow,
                &config.execution.release_devtools_policy,
            );
            out.push_str(super::CACHED_RUNTIME_END);
            out.push_str(super::CACHED_CORE_BEGIN);
            let test_harness = emitter.artifact.harness.is_some()
                || matches!(
                    emitter.artifact.kind,
                    MirArtifactKind::TestExecutable
                        | MirArtifactKind::FuzzExecutable
                        | MirArtifactKind::TestOverride
                );
            super::push_full_corelib_prelude_with_policy(
                out,
                active_os,
                test_harness,
                &program.facts.edition,
                &emitter.artifact.runtime_parts,
                mir_program_uses_shared_kernel(program),
                uses_arrow,
                &config.execution.release_devtools_policy,
            );
            // Bridge macros are declared in the Core block, and their concrete
            // entry points (`jet_http_build_*`) live there too, so they are
            // realized inside it: the runtime/program split keeps every bridge
            // item in the `jet_runtime` crate that declares and exports them.
            if let Some(link) = config.execution.ffi {
                let needs_http_bridge = program.prelude_calls.iter().any(|call| {
                    let symbol = match &call.symbol {
                        MirSymbol::Prelude(symbol) | MirSymbol::Runtime(symbol) => symbol.as_str(),
                    };
                    matches!(
                        symbol,
                        "jet_http_client_get"
                            | "jet_http_client_post"
                            | "jet_http_client_request_send"
                            | "jet_http_build_resolve"
                            | "jet_http_build_get"
                    )
                });
                if needs_http_bridge {
                    let _ = writeln!(out, "jet_http_client_bridge!({});", link.crate_name);
                }
                let needs_net_tls_client_bridge = program.prelude_calls.iter().any(|call| {
                    is_net_tls_client_bridge_call(&call.symbol)
                });
                if needs_net_tls_client_bridge {
                    let _ = writeln!(out, "jet_net_tls_client_bridge!({});", link.crate_name);
                }
                let needs_plugin_bridge = program.prelude_calls.iter().any(|call| {
                    matches!(&call.symbol, MirSymbol::Prelude(symbol) if symbol == "jet_plugin_load")
                });
                if needs_plugin_bridge {
                    let _ = writeln!(out, "jet_plugin_bridge!({});", link.crate_name);
                }
                let needs_db_bridge = program.prelude_calls.iter().any(|call| {
                    let symbol = match &call.symbol {
                        MirSymbol::Prelude(symbol) | MirSymbol::Runtime(symbol) => symbol.as_str(),
                    };
                    symbol.starts_with("jet_db_")
                });
                if needs_db_bridge {
                    let _ = writeln!(out, "jet_db_bridge!({});", link.crate_name);
                }
                let needs_vault_display_bridge = program.prelude_calls.iter().any(|call| {
                    let symbol = match &call.symbol {
                        MirSymbol::Prelude(symbol) | MirSymbol::Runtime(symbol) => symbol.as_str(),
                    };
                    symbol
                        .rsplit("::")
                        .next()
                        .is_some_and(|symbol| symbol.starts_with("jet_vault_"))
                });
                if needs_vault_display_bridge {
                    let _ = writeln!(out, "jet_vault_display_bridge!({});", link.crate_name);
                }
            }
            out.push_str(super::CACHED_CORE_END);
            out.push_str("\n// JET_VETTED_UNSAFE_BEGIN: jet_program_allocator\n\
                // AUDIT: the shared allocator kernel uses System only for its own\n\
                // allocation-free bookkeeping; the checked cap is installed by the program.\n\
                pub mod jet_program_allocator {\n");
            out.push_str(include_str!("../Prelude/ProgramAllocator.rs"));
            out.push_str("\n}\n// JET_VETTED_UNSAFE_END: jet_program_allocator\n");
            out.push('\n');
        }
    }
}

/// Runtime prefix of one artifact: the runtime/Core block plus the coverage
/// prelude. The self-hosted Jet emitter produces user items only; its host
/// prepends exactly this text so both compilers link the same `jet_runtime`
/// rlib through `jet_store::runtime::prepare`.
pub fn emit_mir_runtime_text(program: &MirProgram, config: &MirRustConfig<'_>) -> String {
    let artifact_identity = program
        .artifact_identity(config.execution.artifact)
        .unwrap_or_else(|error| {
            panic!("MIR runtime text requires canonical artifact identity: {error}")
        });
    let emitter = RustEmitter::new(program, config, artifact_identity);
    let mut out = String::new();
    emit_runtime_block(&emitter, program, config, &mut out);
    if emitter.coverage_enabled() {
        super::push_coverage_prelude(&mut out);
    }
    out
}

/// Measurement only: never admit an artifact after any failed item.
struct EmissionCensus {
    enabled: bool,
    attempted: usize,
    failures: usize,
    first_panic: Option<Box<dyn std::any::Any + Send>>,
}

impl EmissionCensus {
    fn new() -> Self {
        Self {
            enabled: std::env::var("JET_DEBUG_LOWER_ALL").is_ok_and(|value| value == "1"),
            attempted: 0,
            failures: 0,
            first_panic: None,
        }
    }

    fn item(
        &mut self,
        kind: &str,
        id: u64,
        name: &str,
        span: std::ops::Range<usize>,
        out: &mut String,
        emit: impl FnOnce(&mut String),
    ) -> bool {
        if !self.enabled {
            emit(out);
            return true;
        }
        self.attempted += 1;
        let start = out.len();
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| emit(out))) {
            Ok(()) => true,
            Err(payload) => {
                out.truncate(start);
                self.failures += 1;
                let message = emission_panic_message(payload.as_ref());
                let quoted_name = jet_foundation::JSON::json_escape(name);
                let quoted_message = jet_foundation::JSON::json_escape(message);
                eprintln!(
                    "JET_DEBUG_LOWER_ALL emission: kind={kind} id={id} name=\"{}\" span={}..{} message=\"{}\"",
                    quoted_name,
                    span.start,
                    span.end,
                    quoted_message,
                );
                let _ = writeln!(
                    out,
                    "// JET_DEBUG_LOWER_ALL FAILED EMISSION: kind={kind} id={id} name=\"{quoted_name}\" span={}..{} message=\"{quoted_message}\"",
                    span.start, span.end,
                );
                if self.first_panic.is_none() {
                    self.first_panic = Some(payload);
                }
                false
            }
        }
    }

    fn finish(self, out: &mut String, program_start: usize) {
        if self.enabled {
            eprintln!(
                "JET_DEBUG_LOWER_ALL emission failures {} of {}",
                self.failures, self.attempted,
            );
            match dump_partial_rust(&out.as_bytes()[program_start..], self.failures, self.attempted) {
                Ok(path) => eprintln!(
                    "JET_DEBUG_LOWER_ALL emission partial Rust: path=\"{}\" failures={} items={}",
                    jet_foundation::JSON::json_escape(&path.to_string_lossy()),
                    self.failures, self.attempted,
                ),
                Err(error) => {
                    eprintln!("JET_DEBUG_LOWER_ALL emission partial Rust failed: {error}");
                    if self.first_panic.is_none() {
                        panic!("cannot write partial Rust emission census: {error}");
                    }
                }
            }
        }
        if let Some(payload) = self.first_panic {
            out.truncate(program_start);
            // Keep the original failure and the caller's existing ICE/exit-101
            // path; collecting evidence must not turn a panic into success.
            std::panic::resume_unwind(payload);
        }
    }
}

fn emission_panic_message(payload: &(dyn std::any::Any + Send)) -> &str {
    if let Some(message) = payload.downcast_ref::<String>() {
        message
    } else if let Some(message) = payload.downcast_ref::<&str>() {
        message
    } else {
        "non-string panic payload"
    }
}

fn dump_partial_rust(
    rust: &[u8],
    failures: usize,
    attempted: usize,
) -> std::io::Result<std::path::PathBuf> {
    use std::io::Write;
    let path = match std::env::var_os("JET_DUMP_RUST") {
        Some(path) => std::path::PathBuf::from(path),
        None => {
            static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
            let sequence = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            std::env::temp_dir().join(format!(
                "jet-emission-{}-{sequence}.partial.rs", std::process::id(),
            ))
        }
    };
    let mut file = std::fs::File::create(&path)?;
    writeln!(
        file,
        "// DEBUG PARTIAL RUST: NOT AN ADMITTED BUILD ARTIFACT; emission failures {failures} of {attempted}"
    )?;
    file.write_all(rust)?;
    Ok(path)
}

#[cfg(test)]
mod emission_census_tests {
    use super::{emission_panic_message, EmissionCensus};

    #[test]
    fn reports_all_bad_items_only_in_collect_mode() {
        const CHILD: &str = "JET_TEST_EMISSION_CENSUS_CHILD";
        if let Ok(mode) = std::env::var(CHILD) {
            let mut census = EmissionCensus::new();
            let mut out = String::from("prefix");
            let mut reached_last = false;
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                census.item("type", 11, "bad \"type\"", 3..7, &mut out, |out| {
                    out.push_str("struct GoodType;\n");
                    if mode != "success" {
                        out.push_str("partial-type");
                        std::panic::panic_any(String::from("bad type\n\"first\""));
                    }
                });
                census.item("impl", 12, "bad impl", 7..9, &mut out, |out| {
                    out.push_str("impl GoodType {}\n");
                    if mode != "success" {
                        out.push_str("partial-impl");
                        panic!("bad impl second");
                    }
                });
                census.item("function", 13, "good", 9..10, &mut out, |out| {
                    out.push_str("fn main() {}\n");
                    if mode == "rustc-errors" {
                        out.push_str("fn first_bad() -> u8 { false }\nfn second_bad() -> u8 { \"bad\" }\n");
                    }
                    reached_last = true;
                });
                if mode != "success" {
                    assert!(!out.contains("partial-type") && !out.contains("partial-impl"));
                    assert_eq!(out.matches("// JET_DEBUG_LOWER_ALL FAILED EMISSION:").count(), 2);
                }
                census.finish(&mut out, "prefix".len());
            }));
            if mode == "success" {
                assert!(result.is_ok());
                assert!(reached_last);
            } else {
                let payload = result.expect_err("an emission failure must remain an ICE");
                assert!(payload.downcast_ref::<String>().is_some());
                assert_eq!(emission_panic_message(payload.as_ref()), "bad type\n\"first\"");
                assert_eq!(reached_last, mode != "normal");
                if mode != "normal" {
                    assert_eq!(out, "prefix", "a failed program must not publish partial Rust");
                }
            }
            return;
        }

        // A subprocess exercises the real environment gate without mutating
        // process-global environment or panic hooks beside sibling tests.
        let module = module_path!().split_once("::").unwrap().1;
        let test = format!("{module}::reports_all_bad_items_only_in_collect_mode");
        let directory = std::env::temp_dir().join(format!(
            "jet-emission-census-{}-{}",
            std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),
        ));
        std::fs::create_dir(&directory).unwrap();
        for mode in ["collect", "normal", "success", "rustc-errors"] {
            let dump = directory.join(format!("{mode}.partial.rs"));
            let mut command = std::process::Command::new(std::env::current_exe().unwrap());
            command.args(["--exact", &test, "--nocapture"])
                .env(CHILD, mode).env("JET_DUMP_RUST", &dump);
            if mode == "normal" {
                command.env_remove("JET_DEBUG_LOWER_ALL");
            } else {
                command.env("JET_DEBUG_LOWER_ALL", "1");
            }
            let output = command.output().unwrap();
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            assert!(output.status.success(), "{mode}: {stdout}\n{stderr}");
            assert!(stdout.contains("1 passed"), "{mode}: child test was not selected: {stdout}");
            let rows = stderr.lines()
                .filter(|line| line.starts_with("JET_DEBUG_LOWER_ALL emission:"))
                .collect::<Vec<_>>();
            match mode {
                "collect" | "rustc-errors" => {
                    assert_eq!(rows.len(), 2, "{stderr}");
                    assert!(rows[0].contains(
                        "kind=type id=11 name=\"bad \\\"type\\\"\" span=3..7 message=\"bad type\\n\\\"first\\\"\""
                    ), "{stderr}");
                    assert!(rows[1].contains(
                        "kind=impl id=12 name=\"bad impl\" span=7..9 message=\"bad impl second\""
                    ), "{stderr}");
                    assert!(stderr.contains("JET_DEBUG_LOWER_ALL emission failures 2 of 3"));
                }
                "normal" => {
                    assert!(rows.is_empty(), "{stderr}");
                    assert!(!stderr.contains("bad impl second"), "{stderr}");
                    assert!(!stderr.contains("emission failures"), "{stderr}");
                    assert!(!dump.exists(), "normal mode must ignore the diagnostic dump path");
                    continue;
                }
                "success" => {
                    assert!(rows.is_empty(), "{stderr}");
                    assert!(stderr.contains("JET_DEBUG_LOWER_ALL emission failures 0 of 3"));
                }
                _ => unreachable!(),
            }
            assert!(stderr.contains("JET_DEBUG_LOWER_ALL emission partial Rust: path="));
            let rust = std::fs::read_to_string(&dump).unwrap();
            assert!(rust.starts_with("// DEBUG PARTIAL RUST: NOT AN ADMITTED BUILD ARTIFACT;"));
            assert!(!rust.contains("prefix") && !rust.contains("partial-type") && !rust.contains("partial-impl"));
            assert!(rust.contains("fn main() {}"));
            assert_eq!(rust.matches("// JET_DEBUG_LOWER_ALL FAILED EMISSION:").count(),
                if mode == "success" { 0 } else { 2 });
            let rustc = std::process::Command::new(
                std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into()),
            ).args(["--emit=metadata", "--crate-type=lib", "--crate-name=census_partial"])
                .arg(&dump).arg("-o").arg(directory.join(format!("{mode}.rmeta")))
                .output().unwrap();
            let diagnostics = String::from_utf8_lossy(&rustc.stderr);
            if mode == "rustc-errors" {
                assert!(!rustc.status.success());
                assert_eq!(diagnostics.matches("error[E0308]").count(), 2, "{diagnostics}");
            } else {
                assert!(rustc.status.success(), "{diagnostics}");
            }
        }
        std::fs::remove_dir_all(directory).unwrap();
    }
}

/// Append a complete Rust fragment from optimized canonical MIR.
pub fn emit_mir_program_into(program: &MirProgram, config: &MirRustConfig, out: &mut String) {
    let canonical_input = CanonicalPass::enabled().then(|| canonical_payload(program));
    let canonical_input_identity = CanonicalPass::enabled().then(|| canonical_identity(program));
    if let Err(error) = program.cffi.validate_boundaries() {
        panic!("MIR Rust emission received invalid foreign boundary facts: {error}");
    }
    let artifact_identity = program
        .artifact_identity(config.execution.artifact)
        .unwrap_or_else(|error| {
            panic!("MIR Rust emission requires canonical artifact identity: {error}")
        });
    let emitter = RustEmitter::new(program, config, artifact_identity.clone());
    let program_start = out.len();
    let mut census = EmissionCensus::new();
    let target_supports_atomic =
        program
            .facts
            .target_dossier
            .machine
            .as_deref()
            .is_some_and(|machine| {
                machine
                    .provides_capability(jet_foundation::TargetMachine::TargetCapability::Atomic64)
            });
    assert!(
        !mir_program_uses_atomic_word(program) || target_supports_atomic,
        "MIR Atomic<T> reached Rust emission without Target.Atomic64 sema admission for target `{}`",
        config.target.triple
    );
    let mut emitted_methods = BTreeSet::new();
    census.item("support", emitter.artifact.id.0, "runtime", 0..0, out,
        |out| emit_runtime_block(&emitter, program, config, out));
    // Program items go to their build unit's section (see `EmissionUnits`);
    // without units every sink is `out` itself.
    let mut units = EmissionUnits::new(program);
    if emitter.coverage_enabled() {
        super::push_coverage_prelude(EmissionUnits::sink(&mut units, out, None));
    }
    census.item("support", emitter.artifact.id.0, "hardware-facts", 0..0,
        EmissionUnits::sink(&mut units, out, None),
        |out| emitter.emit_hardware_facts(out));
    if !emitter.is_no_os() {
        if let jet_foundation::TargetMachine::AllocatorPolicy::Counting { cap } =
            &program.facts.program_allocator
        {
            let bytes = cap.map_or(u64::MAX, |size| size.bytes);
            let _ = writeln!(
                EmissionUnits::sink(&mut units, out, None),
                "#[global_allocator]\nstatic __JET_PROGRAM_ALLOCATOR: {}jet_program_allocator::JetProgramAllocator = {}jet_program_allocator::JetProgramAllocator::counting({bytes});",
                config.root_prefix, config.root_prefix,
            );
        }
    }
    EmissionUnits::sink(&mut units, out, None).push('\n');

    if config.execution.emit_metadata {
        census.item("support", emitter.artifact.id.0, "program-metadata", 0..0,
            EmissionUnits::sink(&mut units, out, None), |out| {
                emitter.emit_program_metadata(out);
                emitter.emit_modules_and_imports(out);
            });
    }
    if config.execution.emit_types {
        for handle in &program.handles {
            if handle.payload.library != "core.process" {
                census.item("handle", handle.id.0, &handle.payload.typedef_name, 0..0,
                    EmissionUnits::sink(&mut units, out, None),
                    |out| emitter.emit_handle_type(handle, out));
            }
        }
        let carrierless_records = emitter.used_carrierless_core_records();
        for def in &program.types {
            let unit = units.as_ref().map(|units| units.module_unit(def.module, def.span.start));
            if emitter.declares_type_def(def) || carrierless_records.contains(&def.id) {
                census.item("type", def.id.0, &def.key, def.span.start..def.span.end,
                    EmissionUnits::sink(&mut units, out, unit),
                    |out| emitter.emit_type_def(def, out));
            }
        }
        census.item("support", emitter.artifact.id.0, "history-strategies", 0..0,
            EmissionUnits::sink(&mut units, out, None),
            |out| emitter.emit_history_strategies(out));
        for trait_def in &program.traits {
            let emit_compiler_rollback = trait_def.name == crate::Syntax::TRAIT_ROLLBACK;
            if emitter.module_selected(trait_def.module)
                && (emit_compiler_rollback
                    || (!crate::Codegen::TIR::tir_to_mir_types::is_compiler_owned_trait(
                        &trait_def.name,
                    ) && !crate::Codegen::TIR::tir_to_mir_types::is_compiler_owned_trait(
                        &trait_def.key,
                    )))
            {
                let unit = units
                    .as_ref()
                    .map(|units| units.module_unit(trait_def.module, trait_def.span.start));
                if !census.item("trait", trait_def.id.0, &trait_def.key,
                    trait_def.span.start..trait_def.span.end,
                    EmissionUnits::sink(&mut units, out, unit),
                    |out| emitter.emit_trait_def(trait_def, &mut emitted_methods, out))
                {
                    // The failed trait owns its default bodies. Do not report
                    // those again as methods without an implementation row.
                    emitted_methods.extend(trait_def.methods.iter().filter_map(|method| method.default));
                }
            }
        }
        // Card #4258: a constant whose every read was copied into its use
        // sites (TIR→MIR `inline_known_constant_reads`) needs no accessor;
        // storage cells and every constant still read through `Global` keep
        // their item.
        let global_reads = program
            .functions
            .iter()
            .flat_map(|function| &function.blocks)
            .flat_map(|block| &block.instructions)
            .filter_map(|instruction| match &instruction.operation {
                MirOperation::Global { name } => Some(name.as_str()),
                _ => None,
            })
            .collect::<HashSet<_>>();
        for constant in &program.constants {
            if emitter.module_selected(constant.module)
                && (constant.is_storage || global_reads.contains(constant.key.as_str()))
            {
                let unit = units
                    .as_ref()
                    .map(|units| units.module_unit(constant.module, constant.span.start));
                census.item("constant", constant.id.0, &constant.key,
                    constant.span.start..constant.span.end,
                    EmissionUnits::sink(&mut units, out, unit),
                    |out| emitter.emit_constant_def(constant, out));
            }
        }
    }
    census.item("support", emitter.artifact.id.0, "link-closure", 0..0,
        EmissionUnits::sink(&mut units, out, None),
        |out| emitter.emit_link_closure(out));
    emitter.emit_c_abi_records(EmissionUnits::sink(&mut units, out, None), &mut census);
    if config.execution.emit_foreign {
        for foreign in &program.foreign {
            if emitter.module_selected(foreign.module_id) {
                let unit = units
                    .as_ref()
                    .map(|units| units.module_unit(foreign.module_id, foreign.span.start));
                census.item("foreign", foreign.id.0, &foreign.key,
                    foreign.span.start..foreign.span.end,
                    EmissionUnits::sink(&mut units, out, unit),
                    |out| emitter.emit_foreign(foreign, out));
            }
        }
    }
    emitter.emit_callback_trampolines(EmissionUnits::sink(&mut units, out, None), &mut census);
    let codec_keep = demanded_codec_impls(program);
    for (index, implementation) in program.impls.iter().enumerate() {
        if !emitter.module_selected(implementation.module)
            || !emitter.impl_selected_for_target(implementation)
        {
            continue;
        }
        if !codec_keep[index] || emitter.runtime_carrier_trait_impl(implementation) {
            emitted_methods.extend(implementation.methods.iter().copied());
            continue;
        }
        // Rust's orphan rule: an impl of a runtime trait must live in the
        // crate declaring its self type, so it follows the type's unit.
        let unit = units.as_ref().map(|units| match emitter.impl_self_type_def(implementation) {
            Some(def) => units.module_unit(def.module, def.span.start),
            None => units.module_unit(implementation.module, implementation.span.start),
        });
        if !census.item("impl", implementation.id.0, &implementation.key,
            implementation.span.start..implementation.span.end,
            EmissionUnits::sink(&mut units, out, unit),
            |out| emitter.emit_impl(implementation, &mut emitted_methods, out))
        {
            // Skip the whole failed impl, including bodies it did not reach.
            emitted_methods.extend(implementation.methods.iter().copied());
        }
    }
    for function in &program.functions {
        if !emitter.module_selected(function.module_id) || !emitter.selected_for_target(function) {
            continue;
        }
        match &function.form {
            MirFunctionForm::TopLevel => {
                let unit = units
                    .as_ref()
                    .map(|units| units.file_unit(function.source_file, function.span.start));
                census.item("function", function.id.0, &function.key,
                    function.span.start..function.span.end,
                    EmissionUnits::sink(&mut units, out, unit),
                    |out| emitter.emit_function(function, out));
            }
            MirFunctionForm::Method { .. } | MirFunctionForm::TraitMethod { .. } => {
                if !emitted_methods.contains(&function.id) {
                    census.item("function", function.id.0, &function.key,
                        function.span.start..function.span.end, out, |_| {
                            panic!("MIR method {:?} has no selected implementation row", function.id);
                        });
                }
            }
        }
    }
    if let Some(units) = units {
        units.write_sections(out);
    }
    census.item("support", emitter.artifact.id.0, "web-data-registration", 0..0, out,
        |out| emitter.emit_web_data_type_registration(out));
    emitter.emit_exports(out, &mut census);
    census.item("support", emitter.artifact.id.0, "entry", 0..0, out,
        |out| emitter.emit_entry(out));
    census.item("support", emitter.artifact.id.0, "harness", 0..0, out,
        |out| emitter.emit_harness(out));
    for encoder in emitter.history_capture_encoders.borrow().values() {
        out.push_str(encoder);
    }
    for arity in emitter.history_callable_arities.borrow().iter() {
        if matches!(*arity, 0 | 1 | 3) {
            continue;
        }
        census.item("support", *arity as u64, "history-callable", 0..0, out, |out| {
        let args = (0..*arity)
            .map(|index| format!(", A{index}"))
            .collect::<String>();
        let _ = writeln!(out, "jet_history_callable!(JetHistoryFn{arity}{args});");
        });
    }
    for (arity, modes) in emitter.history_callable_modes.borrow().iter() {
        census.item("support", *arity as u64, modes, 0..0, out, |out| {
        let args = modes
            .chars()
            .enumerate()
            .map(|(index, mode)| {
                let mode = match mode {
                    'O' => "owned",
                    'R' => "read",
                    'S' => "text",
                    'W' => "write",
                    other => panic!("MIR history callable has unknown mode `{other}`"),
                };
                format!("A{index} => {mode}")
            })
            .collect::<Vec<_>>()
            .join(", ");
        let _ = writeln!(
            out,
            "jet_history_callable!(JetHistoryFn{arity}B{modes}; {args});"
        );
        });
    }
    census.finish(out, program_start);
    if let (Some(canonical_input), Some(canonical_input_identity)) =
        (canonical_input, canonical_input_identity)
    {
        CanonicalPass::record(
            "lowering",
            "mir.rust-emitter",
            "crates/jet-codegen/src/Codegen/MIRRust.rs",
            "mir",
            canonical_input,
            canonical_input_identity,
            "mir",
            CanonicalPass::debug_payload(
                "mir",
                "mir.rust-emitter",
                &(out, artifact_identity.clone(), &config.target.triple),
            ),
            format!(
                "{{\"representation\":\"mir\",\"artifact_id\":\"{}\",\"target\":\"{}\"}}",
                artifact_identity.artifact.0,
                jet_foundation::JSON::json_escape(&config.target.triple),
            ),
            "checked",
        );
    }
    CanonicalPass::persist_process("emit");
}

/// Provenance line the bootstrap assembler (`Compiler/Bootstrap/assemble.mjs`)
/// writes before each original `Compiler/<Package>/…` file it concatenates
/// into the one compiler unit.
const UNIT_PROVENANCE_MARKER: &str = "// [jet-bootstrap source: ";
/// Opens one build-unit section of an emitted program; packaging builds each
/// section as its own crate. Single-crate consumers only see comments.
pub const UNIT_BEGIN_MARKER: &str = "// jet:unit-begin ";
/// Closes the build-unit section named after it.
pub const UNIT_END_MARKER: &str = "// jet:unit-end ";
/// The unit beneath every package: Core items, compiler-synthesized rows and
/// anything outside a marked source range.
const BASE_UNIT: &str = "base";

/// Build units of one emitted program. An item's unit is the package of the
/// original file whose provenance marker is in effect at the item's span, so
/// the assembled compiler splits into one crate per `Compiler/<Package>`.
/// Programs with fewer than two units are not split.
struct EmissionUnits {
    /// Per source file: (byte offset where a marked file's text starts, unit),
    /// in source order.
    starts: HashMap<MirSourceFileId, Vec<(usize, String)>>,
    module_files: HashMap<MirModuleId, MirSourceFileId>,
    sections: BTreeMap<String, String>,
}

impl EmissionUnits {
    fn new(program: &MirProgram) -> Option<Self> {
        let mut starts = HashMap::new();
        let mut names = BTreeSet::new();
        for file in &program.source_files {
            let mut rows = Vec::new();
            let mut offset = 0;
            for line in file.source.split_inclusive('\n') {
                offset += line.len();
                let Some(path) = line
                    .strip_prefix(UNIT_PROVENANCE_MARKER)
                    .and_then(|rest| rest.trim_end().strip_suffix(']'))
                else {
                    continue;
                };
                let unit = path.split('/').nth(1).unwrap_or(BASE_UNIT).to_string();
                names.insert(unit.clone());
                rows.push((offset, unit));
            }
            if !rows.is_empty() {
                starts.insert(file.id, rows);
            }
        }
        if names.len() < 2 {
            return None;
        }
        let module_files = program
            .modules
            .iter()
            .map(|module| (module.id, module.source_file))
            .collect();
        Some(Self {
            starts,
            module_files,
            sections: BTreeMap::new(),
        })
    }

    fn file_unit(&self, file: MirSourceFileId, span_start: usize) -> String {
        let Some(rows) = self.starts.get(&file) else {
            return BASE_UNIT.to_string();
        };
        let after = rows.partition_point(|(start, _)| *start <= span_start);
        after
            .checked_sub(1)
            .map_or(BASE_UNIT, |row| rows[row].1.as_str())
            .to_string()
    }

    fn module_unit(&self, module: MirModuleId, span_start: usize) -> String {
        match self.module_files.get(&module) {
            Some(file) => self.file_unit(*file, span_start),
            None => BASE_UNIT.to_string(),
        }
    }

    /// Where an item goes: its unit's section, or `out` when the program is
    /// not split. `None` is the base unit.
    fn sink<'o>(units: &'o mut Option<Self>, out: &'o mut String, unit: Option<String>) -> &'o mut String {
        match units {
            Some(units) => units
                .sections
                .entry(unit.unwrap_or_else(|| BASE_UNIT.to_string()))
                .or_default(),
            None => out,
        }
    }

    /// The base section first, then each package section, each between its
    /// begin/end markers.
    fn write_sections(mut self, out: &mut String) {
        let base = self.sections.remove(BASE_UNIT).unwrap_or_default();
        for (name, text) in std::iter::once((BASE_UNIT.to_string(), base)).chain(self.sections) {
            let _ = writeln!(out, "{UNIT_BEGIN_MARKER}{name}");
            out.push_str(&text);
            if !text.ends_with('\n') {
                out.push('\n');
            }
            let _ = writeln!(out, "{UNIT_END_MARKER}{name}");
        }
    }
}

fn select_artifact(
    program: &MirProgram,
    id: MirArtifactId,
    target: MirRustTarget,
) -> &MirArtifactPlan {
    let plan = program
        .artifacts
        .iter()
        .find(|plan| plan.id == id)
        .unwrap_or_else(|| panic!("MIR artifact ID {:?} has no plan row", id));
    let target_ok = match (target, plan.target) {
        (MirRustTarget::Native, MirArtifactTarget::RustAot) => true,
        (MirRustTarget::WebWasm, MirArtifactTarget::Web) => true,
        (MirRustTarget::Native, MirArtifactTarget::Interpreter | MirArtifactTarget::Web)
        | (MirRustTarget::WebWasm, MirArtifactTarget::RustAot | MirArtifactTarget::Interpreter) => {
            false
        }
    };
    let kind_ok = match (target, plan.kind) {
        (
            MirRustTarget::Native,
            MirArtifactKind::NativeExecutable
            | MirArtifactKind::NativeLibrary
            | MirArtifactKind::SandboxPlugin
            | MirArtifactKind::TestExecutable
            | MirArtifactKind::FuzzExecutable
            | MirArtifactKind::TestOverride,
        ) => true,
        (MirRustTarget::WebWasm, MirArtifactKind::WebApplication) => true,
        (MirRustTarget::Native, MirArtifactKind::WebApplication)
        | (
            MirRustTarget::WebWasm,
            MirArtifactKind::NativeExecutable
            | MirArtifactKind::NativeLibrary
            | MirArtifactKind::SandboxPlugin
            | MirArtifactKind::TestExecutable
            | MirArtifactKind::FuzzExecutable
            | MirArtifactKind::TestOverride,
        ) => false,
    };
    if !target_ok || !kind_ok {
        panic!(
            "MIR artifact {:?} kind {} is not applicable to {:?} Rust emission",
            id,
            plan.kind.as_str(),
            target
        );
    }
    if plan.modules.is_empty() {
        panic!("MIR artifact {:?} has no selected module rows", id);
    }
    plan
}

fn function_has_debug_only(function: &MirFunction) -> bool {
    function
        .scopes
        .iter()
        .any(|scope| scope.kind == MirScopeKind::DebugOnly)
}

fn debug_only_block_states(function: &MirFunction) -> BTreeMap<MirBlockId, bool> {
    let debug_scopes = function
        .scopes
        .iter()
        .filter(|scope| scope.kind == MirScopeKind::DebugOnly)
        .map(|scope| scope.id)
        .collect::<HashSet<_>>();
    let is_debug_scope = |scope_id: MirScopeId| debug_scopes.contains(&scope_id);
    let positions = block_positions(function);
    let mut states = BTreeMap::new();
    states.insert(function.entry, false);
    let mut pending = vec![function.entry];
    while let Some(block_id) = pending.pop() {
        let Some(position) = positions.get(&block_id) else {
            continue;
        };
        let block = &function.blocks[*position];
        let mut active = states.get(&block_id).copied().unwrap_or(false);
        for instruction in &block.instructions {
            match &instruction.operation {
                MirOperation::ScopeEnter { scope, .. } if is_debug_scope(*scope) => active = true,
                MirOperation::ScopeExit { scope } if is_debug_scope(*scope) => active = false,
                _ => {}
            }
        }
        for target in block.terminator.targets() {
            let next = states.get(&target).copied().unwrap_or(false) || active;
            if states.get(&target).copied() != Some(next) {
                states.insert(target, next);
                pending.push(target);
            }
        }
    }
    states
}

/// Position of each block in `function.blocks`, keyed by block id (the first
/// row wins, as a linear `find` would).
fn block_positions(function: &MirFunction) -> HashMap<MirBlockId, usize> {
    let mut positions = HashMap::with_capacity(function.blocks.len());
    for (position, block) in function.blocks.iter().enumerate() {
        positions.entry(block.id).or_insert(position);
    }
    positions
}

/// Per-function lookup tables, built once per function on first use so the
/// emitter's per-value queries never rescan the function body. MIR
/// validation rejects a value defined twice or given two metadata rows, so
/// each value has at most one row in `definitions` and `values`.
struct FunctionIndex {
    /// (block position, instruction position) of each value's definition.
    definitions: HashMap<MirValueId, (usize, usize)>,
    /// Position of each value's `function.values` row.
    values: HashMap<MirValueId, usize>,
    /// Locals that name the existing SSA value slot, without separate storage.
    bound_local_values: HashMap<MirLocalId, MirValueId>,
    /// Every use of each value in body order: (block position, instruction
    /// position), or `None` for the block's terminator. One row per user.
    uses: HashMap<MirValueId, Vec<(usize, Option<usize>)>>,
    /// (block position, instruction position) of the first `ScopeEnter` that
    /// carries a test member, per scope.
    test_members: HashMap<MirScopeId, (usize, usize)>,
    /// Position of each scope's `function.scopes` row.
    scopes: HashMap<MirScopeId, usize>,
    /// Position of each place's `function.places` row.
    places: HashMap<MirPlaceId, usize>,
    /// The value of the first `Capture` instruction of each capture slot.
    capture_values: HashMap<usize, MirValueId>,
    /// Capture values some place moves out of (`access == Move`).
    moved_captures: HashSet<MirValueId>,
    /// (block position, coverage branch ordinals before the block) per
    /// block id: Branch terminators count once, Switch arms once each.
    blocks: HashMap<MirBlockId, (usize, usize)>,
    /// Positions of the blocks ending in `Jump` to each block, in body order.
    jump_sources: HashMap<MirBlockId, Vec<usize>>,
    /// Predecessor block positions of each block, along terminator edges.
    predecessors: Vec<Vec<usize>>,
    /// D-MEM-COPYSEM1: per local, the (block, instruction) positions of the
    /// operations that may change or release it: a write, move, replace, or
    /// write borrow of one of its places, a write or move call argument
    /// naming one, and any use of a write borrow taken from one.
    local_writes: HashMap<MirLocalId, Vec<(usize, usize)>>,
    /// Locals some operation reaches outside place reads and writes (a
    /// closure capture, a raw address, a by-identity entry list): an
    /// in-place read of one is never proven stable.
    escaped_locals: HashSet<MirLocalId>,
    /// Per parameter index, the (block, instruction) positions of the
    /// operations that may change one of its places, as `local_writes`
    /// counts them for a local, with the place each one changes.
    parameter_writes: HashMap<usize, Vec<(usize, usize, MirPlaceId)>>,
    /// Parameters some operation reaches outside place reads and writes, as
    /// `escaped_locals` counts them, or a drop action releases a place of.
    escaped_parameters: HashSet<usize>,
    /// `stable_local_read` answers per read value, computed on first query.
    stable_reads: std::cell::RefCell<HashMap<MirValueId, bool>>,
}

/// Instructions that change no place and have no effect (constants, place
/// reads, string builds): an operand may be read before or after them alike.
/// Fused split/join and inlined adapter callbacks read their operands at the
/// consumer across such a run.
fn quiet_instructions(instructions: &[MirInstruction]) -> bool {
    instructions.iter().all(|instruction| {
        matches!(
            instruction.operation,
            MirOperation::Constant(_) | MirOperation::ReadPlace(_) | MirOperation::BuildString { .. }
        )
    })
}

/// Coverage branch ordinals a terminator takes.
fn terminator_branch_count(terminator: &MirTerminator) -> usize {
    match terminator {
        MirTerminator::Branch { .. } => 1,
        MirTerminator::Switch { arms, .. } => arms.len(),
        MirTerminator::Jump { .. }
        | MirTerminator::Return { .. }
        | MirTerminator::Yield { .. }
        | MirTerminator::Break { .. }
        | MirTerminator::Continue { .. }
        | MirTerminator::Unreachable { .. }
        | MirTerminator::Poll { .. }
        | MirTerminator::Stopped => 0,
    }
}

/// Whether two places of one root, given by their projections, may share
/// storage: only a field of one record that differs from the other's field
/// at the same depth keeps them apart. An index, payload or other projection
/// is taken to overlap whatever it meets.
fn places_overlap(left: &[MirProjection], right: &[MirProjection]) -> bool {
    for (left, right) in left.iter().zip(right) {
        match (left, right) {
            (MirProjection::Field { field: left, .. }, MirProjection::Field { field: right, .. }) => {
                if left != right {
                    return false;
                }
            }
            _ => return true,
        }
    }
    true
}

impl FunctionIndex {
    fn new(function: &MirFunction) -> Self {
        let mut definitions = HashMap::new();
        let mut uses: HashMap<MirValueId, Vec<(usize, Option<usize>)>> = HashMap::new();
        let mut test_members = HashMap::new();
        let mut capture_values = HashMap::new();
        let bound_local_values: HashMap<MirLocalId, MirValueId> = function.locals.iter()
            .filter_map(|local| local.ssa_value.map(|value| (local.id, value))).collect();
        let bound_place_values: HashMap<MirPlaceId, MirValueId> = if bound_local_values.is_empty() {
            HashMap::new()
        } else {
            function.places.iter().filter_map(|place| match place.base {
                MirPlaceBase::Local(local) => bound_local_values.get(&local).map(|value| (place.id, *value)),
                _ => None,
            }).collect()
        };
        let mut add_use = |value: MirValueId, at: (usize, Option<usize>)| {
            let rows = uses.entry(value).or_default();
            if rows.last() != Some(&at) {
                rows.push(at);
            }
        };
        let mut blocks = HashMap::new();
        let mut jump_sources: HashMap<MirBlockId, Vec<usize>> = HashMap::new();
        let mut branch_ordinal = 0;
        for (block_position, block) in function.blocks.iter().enumerate() {
            blocks
                .entry(block.id)
                .or_insert((block_position, branch_ordinal));
            branch_ordinal += terminator_branch_count(&block.terminator);
            if let MirTerminator::Jump { target } = &block.terminator {
                jump_sources.entry(*target).or_default().push(block_position);
            }
            for (position, instruction) in block.instructions.iter().enumerate() {
                if let Some(result) = instruction.result {
                    definitions.entry(result).or_insert((block_position, position));
                }
                if let MirOperation::ScopeEnter { scope, test_member: Some(_) } =
                    &instruction.operation
                {
                    test_members.entry(*scope).or_insert((block_position, position));
                }
                if let (MirOperation::Capture { slot }, Some(result)) =
                    (&instruction.operation, instruction.result)
                {
                    capture_values.entry(*slot).or_insert(result);
                }
                for value in instruction.operation.value_uses() {
                    add_use(value, (block_position, Some(position)));
                }
                if let MirOperation::ReadPlace(place) | MirOperation::MovePlace { place } = &instruction.operation {
                    if let Some(value) = bound_place_values.get(place) {
                        add_use(*value, (block_position, Some(position)));
                    }
                }
            }
            for value in block.terminator.value_uses() {
                add_use(value, (block_position, None));
            }
        }
        let mut values = HashMap::with_capacity(function.values.len());
        for (position, (value, ..)) in function.values.iter().enumerate() {
            values.entry(*value).or_insert(position);
        }
        let mut scopes = HashMap::with_capacity(function.scopes.len());
        for (position, scope) in function.scopes.iter().enumerate() {
            scopes.entry(scope.id).or_insert(position);
        }
        let mut places = HashMap::with_capacity(function.places.len());
        let mut moved_captures = HashSet::new();
        for (position, place) in function.places.iter().enumerate() {
            places.entry(place.id).or_insert(position);
            if let (MirAccess::Move, MirPlaceBase::Capture(captured)) = (place.access, &place.base) {
                moved_captures.insert(*captured);
            }
        }
        let mut predecessors: Vec<Vec<usize>> = vec![Vec::new(); function.blocks.len()];
        for (block_position, block) in function.blocks.iter().enumerate() {
            for target in block.terminator.targets().iter() {
                if let Some((target, _)) = blocks.get(target) {
                    predecessors[*target].push(block_position);
                }
            }
        }
        let place_local = |place: &MirPlaceId| match places.get(place).map(|row| &function.places[*row].base) {
            Some(MirPlaceBase::Local(local)) => Some(*local),
            _ => None,
        };
        // The parameter index of a place rooted at a parameter, with the place.
        let place_parameter = |place: &MirPlaceId| -> Option<(usize, MirPlaceId)> {
            let MirPlaceBase::Parameter(value) = &function.places[*places.get(place)?].base else {
                return None;
            };
            let (block, position) = definitions.get(value)?;
            match function.blocks[*block].instructions[*position].operation {
                MirOperation::Parameter { index, .. } => Some((index, *place)),
                _ => None,
            }
        };
        let write_borrow = |value: MirValueId| {
            values
                .get(&value)
                .is_some_and(|row| function.values[*row].3.mode == MirOwnershipMode::WriteBorrow)
        };
        let mut local_writes: HashMap<MirLocalId, Vec<(usize, usize)>> = HashMap::new();
        let mut escaped_locals = HashSet::new();
        let mut borrow_roots: HashMap<MirValueId, MirLocalId> = HashMap::new();
        let mut parameter_writes: HashMap<usize, Vec<(usize, usize, MirPlaceId)>> = HashMap::new();
        let mut escaped_parameters = HashSet::new();
        let mut parameter_borrow_roots: HashMap<MirValueId, (usize, MirPlaceId)> = HashMap::new();
        // Two passes: a write borrow's definition may sit in a block listed
        // after one of its uses.
        for pass in 0..2 {
            local_writes.clear();
            parameter_writes.clear();
            for (block_position, block) in function.blocks.iter().enumerate() {
                for (position, instruction) in block.instructions.iter().enumerate() {
                    let mut touched: Vec<MirLocalId> = Vec::new();
                    let mut changed: Vec<(usize, MirPlaceId)> = Vec::new();
                    match &instruction.operation {
                        MirOperation::ReadPlace(place) => {
                            if instruction.result.is_some_and(write_borrow) {
                                touched.extend(place_local(place));
                                changed.extend(place_parameter(place));
                            }
                        }
                        MirOperation::AddressOf { place, access } => {
                            if *access == MirAccess::Move {
                                // A move through an address (a partial move):
                                // later reads go through partial-move slots.
                                escaped_locals.extend(place_local(place));
                                escaped_parameters.extend(place_parameter(place).map(|(index, _)| index));
                            } else if *access != MirAccess::Read {
                                touched.extend(place_local(place));
                                changed.extend(place_parameter(place));
                            }
                        }
                        MirOperation::MovePlace { place }
                            if places
                                .get(place)
                                .is_some_and(|row| !function.places[*row].projections.is_empty()) =>
                        {
                            escaped_locals.extend(place_local(place));
                            escaped_parameters.extend(place_parameter(place).map(|(index, _)| index));
                        }
                        MirOperation::MovePlace { place }
                        | MirOperation::InitializeUninit { place }
                        | MirOperation::WritePlace { place, .. }
                        | MirOperation::ReplacePlace { place, .. }
                        | MirOperation::Semantic(MirSemanticOp::BuiltinMethod {
                            receiver_place: Some(place),
                            ..
                        }) => {
                            touched.extend(place_local(place));
                            changed.extend(place_parameter(place));
                        }
                        // A pattern scan advances its receiver in place.
                        MirOperation::Semantic(
                            MirSemanticOp::CursorTakePattern { receiver_place: place, .. }
                            | MirSemanticOp::ReaderTakePattern { receiver_place: place, .. },
                        ) => changed.extend(place_parameter(place)),
                        MirOperation::RawAddressOf { place } => {
                            escaped_locals.extend(place_local(place));
                            escaped_parameters.extend(place_parameter(place).map(|(index, _)| index));
                        }
                        MirOperation::Closure { captures, .. } => {
                            for capture in captures {
                                if let MirCaptureOperand::Place(place) = capture {
                                    escaped_locals.extend(place_local(place));
                                    escaped_parameters.extend(place_parameter(place).map(|(index, _)| index));
                                }
                            }
                        }
                        _ => {}
                    }
                    let args: &[MirCallArg] = match &instruction.operation {
                        MirOperation::Call { args, .. }
                        | MirOperation::CoreCall { args, .. }
                        | MirOperation::IndirectCall { args, .. }
                        | MirOperation::Semantic(
                            MirSemanticOp::StaticPreludeCall { args, .. }
                            | MirSemanticOp::HardwareCall { args, .. }
                            | MirSemanticOp::ClosureMethod { args, .. }
                            | MirSemanticOp::HostCall { args, .. },
                        ) => args.as_slice(),
                        _ => &[],
                    };
                    for arg in args {
                        if arg.access != MirAccess::Read {
                            touched.extend(arg.place.as_ref().and_then(place_local));
                            changed.extend(arg.place.as_ref().and_then(place_parameter));
                        }
                    }
                    for value in instruction.operation.value_uses() {
                        touched.extend(borrow_roots.get(&value).copied());
                        changed.extend(parameter_borrow_roots.get(&value).copied());
                    }
                    if let Some(result) = instruction.result.filter(|result| write_borrow(*result)) {
                        if let Some(local) = touched.first() {
                            borrow_roots.insert(result, *local);
                        }
                        if let Some(root) = changed.first() {
                            parameter_borrow_roots.insert(result, *root);
                        }
                    }
                    if pass == 1 {
                        for local in touched {
                            local_writes.entry(local).or_default().push((block_position, position));
                        }
                        for (parameter, place) in changed {
                            parameter_writes
                                .entry(parameter)
                                .or_default()
                                .push((block_position, position, place));
                        }
                    }
                }
            }
        }
        for action in &function.drops {
            escaped_parameters.extend(place_parameter(&action.place).map(|(index, _)| index));
        }
        Self {
            definitions,
            values,
            bound_local_values,
            uses,
            test_members,
            scopes,
            places,
            capture_values,
            moved_captures,
            blocks,
            jump_sources,
            predecessors,
            local_writes,
            escaped_locals,
            parameter_writes,
            escaped_parameters,
            stable_reads: std::cell::RefCell::new(HashMap::new()),
        }
    }
}

/// Deepest indentation (in columns) a structured body may reach before the
/// function falls back to the dispatch loop; rustc's recursive passes overflow
/// their stack on a few thousand nested blocks.
const MAX_STRUCTURED_INDENT: usize = 4 * 256;

/// Structured-emission plan of one MIR CFG (the Jet emitter's
/// `jet_rust_emit_cfg_plan`): reverse postorder, loop headers, and the merge
/// blocks each block immediately dominates.
struct MirCfgPlan {
    positions: BTreeMap<MirBlockId, usize>,
    entry: usize,
    /// Reverse postorder number per position; `usize::MAX` when unreachable.
    order: Vec<usize>,
    headers: Vec<bool>,
    merges: Vec<bool>,
    /// The merge blocks each position immediately dominates, latest first.
    follows: Vec<Vec<usize>>,
}

/// Control-flow state of the function body being printed.
struct MirCfgState {
    /// Present while the body is emitted as structured Rust.
    plan: Option<std::rc::Rc<MirCfgPlan>>,
    /// Blocks whose phi reads the dispatch predecessor.
    phi_targets: BTreeSet<MirBlockId>,
    /// Edges whose target subtree is printed in place: (offset in the block
    /// text, target position, indent).
    inline_edges: Vec<(usize, usize, usize)>,
}

/// A phi whose every incoming value is the same value does not depend on the
/// predecessor.
fn phi_is_trivial(incoming: &[(MirBlockId, MirValueId)]) -> bool {
    incoming
        .split_first()
        .is_some_and(|((_, first), rest)| rest.iter().all(|(_, value)| value == first))
}

fn phi_target_blocks(function: &MirFunction) -> BTreeSet<MirBlockId> {
    function
        .blocks
        .iter()
        .filter(|block| {
            block.instructions.iter().any(|instruction| {
                matches!(&instruction.operation, MirOperation::Phi { incoming } if !phi_is_trivial(incoming))
            })
        })
        .map(|block| block.id)
        .collect()
}

/// Calls `visit(line, column, id)` for every `__jet_v_<id>` slot mention in
/// `text`, with `line` counted from the start of `text`.
fn for_each_value_mention(text: &str, visit: impl FnMut(usize, usize, u64)) {
    for_each_slot_mention(text, "__jet_v_", visit);
}

/// Calls `visit(line, column, id)` for every `<prefix><id>` numbered slot
/// mention in `text`, with `line` counted from the start of `text`.
fn for_each_slot_mention(text: &str, prefix: &str, mut visit: impl FnMut(usize, usize, u64)) {
    for (line_index, line) in text.split_inclusive('\n').enumerate() {
        let mut search = 0;
        while let Some(found) = line[search..].find(prefix) {
            let at = search + found;
            let digits_start = at + prefix.len();
            let digits = line[digits_start..]
                .bytes()
                .take_while(|byte| byte.is_ascii_digit())
                .count();
            search = digits_start + digits;
            let joined = line[..at]
                .bytes()
                .next_back()
                .is_some_and(|byte| byte.is_ascii_alphanumeric() || byte == b'_');
            if digits == 0 || joined {
                continue;
            }
            if let Ok(id) = line[digits_start..digits_start + digits].parse::<u64>() {
                visit(line_index, at, id);
            }
        }
    }
}

/// The candidate `<prefix><id>` slots some `body` statement lends to a
/// reference slot: a statement assigning `slot = ..` to a slot whose
/// `let .. = None;` declaration in `text` (the whole function after its
/// signature) names a borrowing type (`&` or a lifetime) and that mentions
/// the candidate. Such a candidate must outlive the reference slot, so it
/// keeps its function-wide declaration.
fn lent_slots(text: &str, body: &str, prefix: &str, candidate: impl Fn(u64) -> bool) -> BTreeSet<u64> {
    let references: BTreeSet<&str> = text
        .lines()
        .filter_map(|line| {
            // A block-local reference ends with its own lexical scope; only
            // references still declared at the function top pin an owner.
            let content = line.strip_prefix("    ")?;
            if content.starts_with(' ') { return None; }
            let rest = content.strip_prefix("let ")?;
            let rest = rest.strip_prefix("mut ").unwrap_or(rest);
            let name = rest.bytes().take_while(|byte| is_identifier_byte(*byte)).count();
            let ty = rest[name..].strip_prefix(": ")?.strip_suffix(" = None;")?;
            (ty.contains('&') || ty.contains('\'')).then_some(&rest[..name])
        })
        .collect();
    let mut lent = BTreeSet::new();
    if references.is_empty() {
        return lent;
    }
    for line in body.lines() {
        let content = line.trim_start_matches(' ');
        let target = content.bytes().take_while(|byte| is_identifier_byte(*byte)).count();
        if !content[target..].starts_with(" = ") || !references.contains(&content[..target]) {
            continue;
        }
        let defined = content[..target].strip_prefix(prefix).and_then(|id| id.parse::<u64>().ok());
        for_each_slot_mention(line, prefix, |_, _, id| {
            if Some(id) != defined && candidate(id) {
                lent.insert(id);
            }
        });
    }
    lent
}

/// Declares block-local `<prefix><id>` slots (`__jet_v_` values or `__jet_l_`
/// locals) at their definition. `out[slots_start..slots_end]` holds the
/// function's slot declarations and everything after it the body. A
/// candidate slot (id -> its Rust type; no observable drop) whose first body
/// mention starts its `slot = Some(..);` statement, and whose later mentions
/// all stay in that statement's lexical scope (no line between them is
/// indented less), and that no statement lends to a reference slot
/// (`lent_slots`), becomes `let mut slot: Option<T> = Some(..);` there; a
/// candidate the body never mentions loses its declaration. Returns where the
/// declarations end.
fn localize_slots(
    out: &mut String,
    slots_start: usize,
    slots_end: usize,
    prefix: &str,
    candidates: &BTreeMap<u64, String>,
) -> usize {
    if candidates.is_empty() {
        return slots_end;
    }
    let mut declared: std::collections::HashMap<u64, usize> = std::collections::HashMap::new();
    for_each_slot_mention(&out[slots_start..slots_end], prefix, |_, _, id| {
        if candidates.contains_key(&id) {
            *declared.entry(id).or_default() += 1;
        }
    });
    struct Mentions {
        first_line: usize,
        first_column: usize,
        on_first_line: usize,
        last_line: usize,
    }
    let body = &out[slots_end..];
    let mut mentions: std::collections::HashMap<u64, Mentions> = std::collections::HashMap::new();
    for_each_slot_mention(body, prefix, |line, column, id| {
        if !candidates.contains_key(&id) {
            return;
        }
        let entry = mentions.entry(id).or_insert(Mentions {
            first_line: line,
            first_column: column,
            on_first_line: 0,
            last_line: line,
        });
        if entry.first_line == line {
            entry.on_first_line += 1;
        }
        entry.last_line = line;
    });
    let lines: Vec<&str> = body.split_inclusive('\n').collect();
    let indents: Vec<usize> = lines
        .iter()
        .map(|line| {
            let content = line.trim_start_matches(' ');
            if content.trim().is_empty() {
                usize::MAX
            } else {
                line.len() - content.len()
            }
        })
        .collect();
    // The first later line indented less than each line closes its scope.
    let mut scope_end = vec![lines.len(); lines.len()];
    let mut open: Vec<usize> = Vec::new();
    for (index, &indent) in indents.iter().enumerate() {
        while let Some(&top) = open.last() {
            if indent >= indents[top] {
                break;
            }
            scope_end[top] = index;
            open.pop();
        }
        open.push(index);
    }
    let pinned = lent_slots(&out[slots_start..], body, prefix, |id| candidates.contains_key(&id));
    let mut localized: BTreeMap<usize, u64> = BTreeMap::new();
    let mut dropped: BTreeSet<u64> = BTreeSet::new();
    for id in candidates.keys() {
        if declared.get(id) != Some(&1) {
            continue;
        }
        let Some(mention) = mentions.get(id) else {
            dropped.insert(*id);
            continue;
        };
        let line = mention.first_line;
        let statement = &lines[line][indents[line]..];
        let defines = mention.on_first_line == 1
            && mention.first_column == indents[line]
            && (statement.starts_with(&format!("{prefix}{id} = Some("))
                || statement.trim_end() == format!("{prefix}{id} = None;"));
        if defines && mention.last_line < scope_end[line] && !pinned.contains(id) {
            localized.insert(line, *id);
            dropped.insert(*id);
        }
    }
    if dropped.is_empty() {
        return slots_end;
    }
    let mut rebuilt = String::with_capacity(out.len() - slots_start);
    for line in out[slots_start..slots_end].split_inclusive('\n') {
        let declared_id = line
            .strip_prefix("    let mut ")
            .and_then(|rest| rest.strip_prefix(prefix))
            .and_then(|rest| rest.split_once(':'))
            .and_then(|(id, _)| id.parse::<u64>().ok());
        if declared_id.is_some_and(|id| dropped.contains(&id)) {
            continue;
        }
        rebuilt.push_str(line);
    }
    let declarations_end = slots_start + rebuilt.len();
    for (index, line) in lines.iter().enumerate() {
        match localized.get(&index) {
            Some(id) => {
                let indent = indents[index];
                let slot = format!("{prefix}{id} = ");
                rebuilt.push_str(&line[..indent]);
                let _ = write!(rebuilt, "let mut {prefix}{id}: Option<{}> = ", candidates[id]);
                rebuilt.push_str(&line[indent + slot.len()..]);
            }
            None => rebuilt.push_str(line),
        }
    }
    out.truncate(slots_start);
    out.push_str(&rebuilt);
    declarations_end
}

fn is_identifier_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_'
}

/// `text` without parentheses that enclose all of it.
fn strip_enclosing_parens(mut text: &str) -> &str {
    while text.starts_with('(') && text.ends_with(')') {
        let mut depth = 0usize;
        let encloses = text.bytes().enumerate().all(|(index, byte)| {
            match byte {
                b'(' => depth += 1,
                b')' => depth = depth.saturating_sub(1),
                _ => {}
            }
            depth > 0 || index == text.len() - 1
        });
        if !encloses {
            break;
        }
        text = &text[1..text.len() - 1];
    }
    text
}

/// `prefix<digits>suffix`: a numbered value or local slot access.
fn numbered_slot_access(text: &str, prefix: &str, suffix: &str) -> bool {
    text.strip_prefix(prefix)
        .and_then(|rest| rest.strip_suffix(suffix))
        .is_some_and(|digits| !digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit()))
}

/// A mangled parameter binding (`__jet_<name>`), not a slot or a symbol.
fn parameter_binding(text: &str) -> bool {
    let Some(name) = text.strip_prefix("__jet_") else {
        return false;
    };
    name.bytes().next().is_some_and(|byte| byte.is_ascii_lowercase())
        && name.bytes().all(is_identifier_byte)
        && !name.starts_with("src_")
        && !numbered_slot_access(name, "l_", "")
        && !numbered_slot_access(name, "v_", "")
        && name != "string"
}

/// `*binding` or `*local`, under any chain of `(..).__jet_field` reads.
fn field_read_place(text: &str) -> bool {
    let text = strip_enclosing_parens(text);
    if let Some(base) = text.strip_prefix('*') {
        return parameter_binding(base)
            || numbered_slot_access(base, "__jet_l_", ".as_ref().expect(\"MIR local\")");
    }
    match text.rsplit_once(").__jet_") {
        Some((head, field)) => {
            !field.is_empty()
                && field.bytes().all(is_identifier_byte)
                && head.strip_prefix('(').is_some_and(field_read_place)
        }
        None => false,
    }
}

/// An expression that only reads slots, bindings or fields, or builds a
/// literal whose type does not depend on its context: evaluating it later in
/// the same straight-line run, with nothing in between naming its variables,
/// observes the same state and infers the same type.
fn pure_slot_expression(expression: &str) -> bool {
    let expression = strip_enclosing_parens(expression);
    if matches!(expression, "true" | "false" | "()") {
        return true;
    }
    if let Some(digits) = expression
        .strip_prefix("jet_foundation::Numeric::JetInt::from_i64(")
        .and_then(|rest| rest.strip_suffix(')'))
    {
        let digits = digits.strip_prefix('-').unwrap_or(digits);
        return !digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit());
    }
    if let Some(text) = expression
        .strip_prefix("{ let mut __jet_string = String::new(); __jet_string.push_str(\"")
        .and_then(|rest| rest.strip_suffix("\"); __jet_string }"))
    {
        let mut escaped = false;
        return text.bytes().all(|byte| {
            let open = escaped || byte != b'"';
            escaped = !escaped && byte == b'\\';
            open
        });
    }
    if expression.starts_with("__jet_src_")
        && expression.contains("::__jet_")
        && expression.bytes().all(|byte| is_identifier_byte(byte) || byte == b':')
    {
        return true;
    }
    numbered_slot_access(expression, "__jet_l_", ".as_ref().expect(\"MIR local\").clone()")
        || numbered_slot_access(expression, "__jet_l_", ".take().expect(\"MIR local\")")
        || numbered_slot_access(expression, "(__jet_v_", ".as_ref().expect(\"MIR value\")).clone()")
        || numbered_slot_access(expression, "*__jet_v_", ".as_ref().expect(\"MIR value\")")
        || numbered_slot_access(expression, "__jet_v_", ".take().expect(\"MIR value\")")
        || expression.strip_suffix(".clone()").is_some_and(field_read_place)
}

/// A closure carrier (`RustEmitter::closure`) whose setup borrows a captured
/// place. Kept in a function-scoped slot, the carrier's drop at function end
/// keeps that borrow alive past every later use of the place; evaluated at
/// its one consumer instead, the borrow ends with the consumer statement.
fn borrowing_closure_expression(expression: &str) -> bool {
    expression
        .strip_prefix("std::rc::Rc::new(std::cell::RefCell::new(Some(Box::new({ let ")
        .map(|body| body.strip_prefix("mut ").unwrap_or(body))
        .and_then(|body| body.strip_prefix("__jet_capture_"))
        .and_then(|body| body.strip_suffix("}))))"))
        .and_then(|body| body.split_once("move |").map(|(setup, _)| setup))
        .is_some_and(|setup| setup.contains(" = &")
            || setup.contains(".as_mut().expect(\"MIR local\")")
            || setup.contains(".as_ref().expect(\"MIR local\")"))
}

fn plain_callable_type(higher_ranked: &str, params: &str, ret: &str, lifetime: &str) -> String {
    format!("std::rc::Rc<std::cell::RefCell<Option<Box<dyn {higher_ranked}FnMut({params}) -> {ret} + {lifetime}>>>>")
}

/// A plain Rc/RefCell callable is invariant in its capture lifetime. A
/// signature can forward a supplied callback lifetime, but a return alone
/// cannot invent one for an owned callable fetched from nominal storage.
/// History's carrier retains its existing factory contract.
fn callback_result_lifetime<'a>(
    mut params: impl Iterator<Item = &'a str>,
    history: bool,
    capture_lifetime: &'static str,
) -> &'static str {
    if history || params.any(|param| {
        (param.contains("FnMut(") || param.contains("JetHistoryFn"))
            && param.contains(capture_lifetime)
    }) {
        capture_lifetime
    } else {
        "'static"
    }
}

fn callback_return_lifetime(params: &[String], history: bool) -> &'static str {
    callback_result_lifetime(params.iter().map(String::as_str), history, "'__jet_callback")
}

fn map_store_callback(value: &str) -> String {
    format!("{{ let __jet_store_value = {value}; move |_| __jet_store_value }}")
}

fn emit_reference_reset(out: &mut String, local: MirLocalId, indent: usize) {
    let _ = writeln!(out, "{:width$}{} = None;", "", local_slot(local), width = indent);
}

fn emit_ref_loan_reset(out: &mut String, node: RefLoanNode, indent: usize) {
    match node {
        RefLoanNode::Local(local) => emit_reference_reset(out, local, indent),
        RefLoanNode::Cursor(cursor) => {
            let _ = writeln!(out, "{:width$}{} = None;", "", value_slot(cursor), width = indent);
        }
        RefLoanNode::Parameter(_) => unreachable!("parameter storage is a loan root, not a slot"),
    }
}

/// Byte offsets of `name` in `text` as a whole identifier, not a field.
fn variable_mentions<'a>(text: &'a str, name: &'a str) -> impl Iterator<Item = usize> + 'a {
    text.match_indices(name).map(|(at, _)| at).filter(move |at| {
        let before = text.as_bytes()[..*at].last().copied();
        let after = text.as_bytes().get(at + name.len()).copied();
        !before.is_some_and(|byte| is_identifier_byte(byte) || byte == b'.')
            && !after.is_some_and(is_identifier_byte)
    })
}

/// `callee(args)`, where Rust sees no disjoint fields through separate
/// `slot.as_mut()`/`slot.as_ref()` calls: two arguments that borrow fields of
/// one local (`&mut ((*l.as_mut()..).a), &((*l.as_ref()..).b)`) conflict
/// (E0499/E0502). When every mention of such a local in `args` is one of
/// those two accesses, the local is borrowed once ahead of the call and each
/// argument projects its field from that one reference. Field borrows of a
/// split owner conflict the same way (`split_partial_field_borrows`).
fn split_local_field_borrows(callee: &str, args: &str) -> String {
    const WRITE: &str = ".as_mut().expect(\"MIR local\")";
    const READ: &str = ".as_ref().expect(\"MIR local\")";
    let (mut bindings, args) = split_partial_field_borrows(args);
    let mut split: Vec<&str> = Vec::new();
    for (at, _) in args.match_indices(WRITE) {
        let digits = args[..at].bytes().rev().take_while(u8::is_ascii_digit).count();
        if digits == 0 || !args[..at - digits].ends_with("__jet_l_") {
            continue;
        }
        let name = &args[at - digits - "__jet_l_".len()..at];
        if split.contains(&name) {
            continue;
        }
        let accesses = args.matches(&format!("{name}{WRITE}")).count()
            + args.matches(&format!("{name}{READ}")).count();
        if accesses >= 2 && variable_mentions(&args, name).count() == accesses {
            split.push(name);
        }
    }
    if split.is_empty() && bindings.is_empty() {
        return format!("{callee}({args})");
    }
    let mut rewritten = args.clone();
    for name in split {
        let binding = format!("__jet_split_{}", &name["__jet_l_".len()..]);
        let write_root = format!("(*(*{name}{WRITE}))");
        let read_root = format!("(*(*{name}{READ}))");
        let accesses = rewritten.matches(&format!("{name}{WRITE}")).count()
            + rewritten.matches(&format!("{name}{READ}")).count();
        if rewritten.matches(&write_root).count() + rewritten.matches(&read_root).count() == accesses {
            // Reborrow the guard's referent once. Repeated DerefMut on the
            // guard would still borrow the whole guard for every argument.
            let _ = write!(bindings, "let {binding} = &mut **{name}{WRITE}; ");
            rewritten = rewritten.replace(&write_root, &format!("(*{binding})"))
                .replace(&read_root, &format!("(*{binding})"));
        } else {
            let _ = write!(bindings, "let {binding} = {name}{WRITE}; ");
            rewritten = rewritten.replace(&format!("{name}{WRITE}"), &binding)
                .replace(&format!("{name}{READ}"), &binding);
        }
    }
    format!("{{ {bindings}{callee}({rewritten}) }}")
}

/// The arms of a split owner's field borrow (`partial_field_reference`).
const PARTIAL_WHOLE_ARM: &str = " { Some(__jet_whole) => ";
const PARTIAL_SPLIT_ARM: &str = ", None => ";

/// One split owner's field borrow, `partial_field_reference`'s
/// `match {slot}.{as_ref|as_mut}() { Some(__jet_whole) => {whole}, None => {split} }`.
struct PartialFieldBorrow<'a> {
    span: std::ops::Range<usize>,
    slot: &'a str,
    mutable: bool,
    whole: &'a str,
    split: &'a str,
}

/// Field borrows of one split owner conflict as the borrows of one local do:
/// each `match slot.as_ref()`/`match slot.as_mut()` borrows all of `slot`
/// (E0499/E0502). When every mention of such an owner in `args` is one of two
/// or more such borrows, at least one mutable, the owner is borrowed once
/// ahead of the call: one destructuring `let` takes every field borrow from
/// the one `&mut` whole, or from the split field slots, and each argument
/// names its binding. A nested owner's borrows in the split arm split the
/// same way. Returns the bindings and the rewritten `args`.
fn split_partial_field_borrows(args: &str) -> (String, String) {
    let mut bindings = String::new();
    let mut args = args.to_string();
    let mut settled: Vec<String> = Vec::new();
    loop {
        let rewrite = {
            let borrows = partial_field_borrows(&args);
            let Some(slot) = borrows.iter()
                .find(|borrow| borrow.mutable && !settled.iter().any(|slot| slot == borrow.slot))
                .map(|borrow| borrow.slot)
            else {
                break;
            };
            settled.push(slot.to_string());
            let owned: Vec<_> = borrows.iter().filter(|borrow| borrow.slot == slot).collect();
            if owned.len() < 2 || variable_mentions(&args, slot).count() != owned.len() {
                continue;
            }
            let stem = slot.strip_prefix("__jet_").unwrap_or(slot);
            let names: Vec<_> = (0..owned.len()).map(|index| format!("__jet_split_whole_{stem}_{index}")).collect();
            let wholes: Vec<_> = owned.iter().map(|borrow| borrow.whole).collect();
            let splits: Vec<_> = owned.iter().map(|borrow| borrow.split).collect();
            let (nested, splits) = split_partial_field_borrows(&splits.join(", "));
            let split = if nested.is_empty() { format!("({splits})") } else { format!("{{ {nested}({splits}) }}") };
            let _ = write!(
                bindings,
                "let ({}) = match {slot}.as_mut() {{ Some(__jet_whole) => ({}), None => {split} }}; ",
                names.join(", "),
                wholes.join(", "),
            );
            let mut rewritten = String::with_capacity(args.len());
            let mut end = 0;
            for (borrow, name) in owned.iter().zip(&names) {
                rewritten.push_str(&args[end..borrow.span.start]);
                rewritten.push_str(name);
                end = borrow.span.end;
            }
            rewritten.push_str(&args[end..]);
            rewritten
        };
        args = rewrite;
    }
    (bindings, args)
}

/// Every split owner field borrow in `text` outside any brace block or
/// closure, where it could sit under a condition or another owner's arm.
fn partial_field_borrows(text: &str) -> Vec<PartialFieldBorrow<'_>> {
    let bytes = text.as_bytes();
    let mut found = Vec::new();
    let mut depth = 0usize;
    let mut quoted = false;
    let mut escaped = false;
    let mut at = 0;
    while at < bytes.len() {
        let byte = bytes[at];
        if quoted {
            quoted = escaped || byte != b'"';
            escaped = !escaped && byte == b'\\';
        } else {
            match byte {
                b'"' => quoted = true,
                b'{' => depth += 1,
                b'}' => depth = depth.saturating_sub(1),
                b'm' if depth == 0 => {
                    if let Some(borrow) = partial_field_borrow(text, at)
                        .filter(|_| !inside_closure(text, at))
                    {
                        at = borrow.span.end;
                        found.push(borrow);
                        continue;
                    }
                }
                _ => {}
            }
        }
        at += 1;
    }
    found
}

/// The split owner field borrow starting at byte `at` of `text`, if any.
fn partial_field_borrow(text: &str, at: usize) -> Option<PartialFieldBorrow<'_>> {
    if text.as_bytes()[..at].last().is_some_and(|byte| is_identifier_byte(*byte)) {
        return None;
    }
    let rest = text[at..].strip_prefix("match ")?;
    let length = rest.bytes().take_while(|byte| is_identifier_byte(*byte)).count();
    let (slot, rest) = rest.split_at(length);
    if slot.is_empty() {
        return None;
    }
    let (mutable, rest) = match rest.strip_prefix(".as_mut()") {
        Some(rest) => (true, rest),
        None => (false, rest.strip_prefix(".as_ref()")?),
    };
    if !rest.starts_with(PARTIAL_WHOLE_ARM) {
        return None;
    }
    let open = text.len() - rest.len() + 1;
    let mut depth = 0usize;
    let mut quoted = false;
    let mut escaped = false;
    let close = text.bytes().enumerate().skip(open).find_map(|(index, byte)| {
        if quoted {
            quoted = escaped || byte != b'"';
            escaped = !escaped && byte == b'\\';
            return None;
        }
        match byte {
            b'"' => quoted = true,
            b'{' => depth += 1,
            b'}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(index);
                }
            }
            _ => {}
        }
        None
    })?;
    let (whole, split) = text[open - 1 + PARTIAL_WHOLE_ARM.len()..close].split_once(PARTIAL_SPLIT_ARM)?;
    Some(PartialFieldBorrow { span: at..close + 1, slot, mutable, whole, split: split.trim_end_matches(' ') })
}

/// The slots and bindings a pure expression reads.
fn expression_variables(expression: &str) -> Vec<&str> {
    let mut names = Vec::new();
    for (at, _) in expression.match_indices("__jet_") {
        let length = expression.as_bytes()[at..].iter().take_while(|byte| is_identifier_byte(**byte)).count();
        let name = &expression[at..at + length];
        let slot = numbered_slot_access(name, "__jet_l_", "") || numbered_slot_access(name, "__jet_v_", "");
        if (slot || parameter_binding(name)) && variable_mentions(expression, name).any(|found| found == at) {
            names.push(name);
        }
    }
    names
}

/// Whether every mention of `name` in `expression` is the lent read capture
/// of a borrowing closure (`let __jet_capture_N = &(*name);`, see
/// `plain_closure`): a shared reborrow of a borrowed Read parameter that
/// copies nothing and shares with the consumer's own reads of it, so folding
/// the closure past those reads reorders nothing.
fn lent_read_mentions_only(expression: &str, name: &str) -> bool {
    let mut mentions = variable_mentions(expression, name).peekable();
    mentions.peek().is_some()
        && mentions.all(|at| {
            expression[..at].ends_with("= &(*") && expression[at + name.len()..].starts_with(");")
        })
}

/// Whether byte `at` of a statement line sits inside a closure body, where a
/// moved expression would run later or not at all. `||` counts as a closure.
fn inside_closure(line: &str, at: usize) -> bool {
    let mut depth = 0usize;
    let mut closures: Vec<usize> = Vec::new();
    let mut quoted = false;
    let mut escaped = false;
    for byte in line.as_bytes()[..at].iter().copied() {
        if quoted {
            quoted = escaped || byte != b'"';
            escaped = !escaped && byte == b'\\';
            continue;
        }
        match byte {
            b'"' => quoted = true,
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => {
                depth = depth.saturating_sub(1);
                while closures.last().is_some_and(|open| *open > depth) {
                    closures.pop();
                }
            }
            b'|' => closures.push(depth),
            _ => {}
        }
    }
    !closures.is_empty()
}

/// One slot definition line: indent, value id, `Some(..)` payload, and whether
/// it assigns a slot declared at the function top.
fn slot_definition(line: &str) -> Option<(usize, u64, &str, bool)> {
    let content = line.trim_end_matches('\n');
    let indent = content.len() - content.trim_start_matches(' ').len();
    let statement = &content[indent..];
    let (hoisted, rest) = match statement.strip_prefix("let mut __jet_v_") {
        Some(rest) => (false, rest),
        None => (true, statement.strip_prefix("__jet_v_")?),
    };
    let digits = rest.bytes().take_while(|byte| byte.is_ascii_digit()).count();
    let id = rest[..digits].parse::<u64>().ok()?;
    let rest = &rest[digits..];
    let payload = if hoisted {
        rest.strip_prefix(" = Some(")?
    } else {
        let rest = rest.strip_prefix(": Option<")?;
        &rest[rest.find("> = Some(")? + "> = Some(".len()..]
    };
    Some((indent, id, payload.strip_suffix(");")?, hoisted))
}

/// Whether the statement at `index` carries an attribute such as
/// `#[cfg(not(jet_release))]` on the line before it.
fn attributed_statement(lines: &[String], index: usize) -> bool {
    index > 0 && lines[index - 1].trim_start().starts_with("#[")
}

/// Folds single-use temporaries into their consumer. `out[slots_start..
/// slots_end]` holds the function's slot declarations and everything after
/// it the body. A body slot defined as `Some(E)` from a pure expression `E`
/// and read once, by the next statement of the same straight-line run (only
/// pure definitions between), as a clone or take of the slot, takes `(E)` in
/// place of that read when nothing else in the consumer or in between names a
/// variable of `E` (an assignment target local excepted, since the right side
/// runs first; a parameter `E` only lends as a read capture excepted, see
/// `lent_read_mentions_only`) and the read is not inside a closure. A hoisted
/// slot defined by a borrowing closure carrier (`borrowing_closure_expression`)
/// folds the same way, as a block typed like the slot. The definition and its
/// top declaration go away. Attributed (debug-only) statements never fold.
/// Returns where the declarations end afterwards.
fn fold_value_slots(out: &mut String, slots_start: usize, slots_end: usize) -> usize {
    let mut mentions: std::collections::HashMap<u64, usize> = std::collections::HashMap::new();
    for_each_value_mention(&out[slots_start..], |_, _, id| *mentions.entry(id).or_default() += 1);
    let body_start = out[slots_start..slots_end].split_inclusive('\n').count();
    let mut lines: Vec<String> = out[slots_start..].split_inclusive('\n').map(str::to_string).collect();
    let mut declarations: std::collections::HashMap<u64, usize> = std::collections::HashMap::new();
    for (index, line) in lines[..body_start].iter().enumerate() {
        let declared = line
            .strip_prefix("    let mut __jet_v_")
            .filter(|rest| rest.trim_end().ends_with("> = None;"))
            .and_then(|rest| rest.split_once(':'))
            .and_then(|(id, _)| id.parse::<u64>().ok());
        if let Some(id) = declared {
            declarations.insert(id, index);
        }
    }
    let mut removed = vec![false; lines.len()];
    let mut folded = false;
    for index in body_start..lines.len() {
        let Some((indent, id, expression, hoisted)) = slot_definition(&lines[index]) else {
            continue;
        };
        let expected = if hoisted { 3 } else { 2 };
        if mentions.get(&id) != Some(&expected)
            || (hoisted && !declarations.contains_key(&id))
            || !(pure_slot_expression(expression)
                || (hoisted && borrowing_closure_expression(expression)))
            || attributed_statement(&lines, index)
        {
            continue;
        }
        let expression = expression.to_string();
        let name = format!("__jet_v_{id}");
        let mut consumer = index + 1;
        while consumer < lines.len() && variable_mentions(&lines[consumer], &name).next().is_none() {
            let skippable = slot_definition(&lines[consumer]).is_some_and(|(other_indent, _, other, _)| {
                other_indent == indent && pure_slot_expression(other)
            }) && !attributed_statement(&lines, consumer);
            if !skippable {
                break;
            }
            consumer += 1;
        }
        let Some(line) = lines.get(consumer) else {
            continue;
        };
        if line.len() - line.trim_start_matches(' ').len() != indent || attributed_statement(&lines, consumer) {
            continue;
        }
        let read = format!("({name}.as_ref().expect(\"MIR value\")).clone()");
        let scalar = format!("(*{name}.as_ref().expect(\"MIR value\"))");
        let take = format!("{name}.take().expect(\"MIR value\")");
        let Some(form) = [read, scalar, take].into_iter().find(|form| line.matches(form.as_str()).count() == 1) else {
            continue;
        };
        let at = line.find(form.as_str()).expect("form occurs once");
        if inside_closure(line, at) {
            continue;
        }
        let (before, after) = (&line[..at], &line[at + form.len()..]);
        let rest = format!("{before}{after}");
        let target = rest
            .trim_start()
            .split_once(" = ")
            .map(|(target, _)| target)
            .filter(|target| numbered_slot_access(target, "__jet_l_", ""));
        let conflict = expression_variables(&expression).into_iter().any(|variable| {
            if lent_read_mentions_only(&expression, variable) {
                return false;
            }
            let allowed = usize::from(Some(variable) == target);
            variable_mentions(&rest, variable).count() > allowed
                || lines[index + 1..consumer]
                    .iter()
                    .any(|between| variable_mentions(between, variable).next().is_some())
        });
        if conflict {
            continue;
        }
        let replaced = if pure_slot_expression(&expression) {
            format!("{before}({expression}){after}")
        } else {
            // A folded closure keeps the slot's declared callable type, so
            // the boxed closure still coerces to its `dyn` carrier.
            let Some(declared) = lines[declarations[&id]]
                .trim_end()
                .split_once(": Option<")
                .and_then(|(_, ty)| ty.strip_suffix("> = None;"))
            else {
                continue;
            };
            format!("{before}{{ let __jet_folded: {declared} = {expression}; __jet_folded }}{after}")
        };
        lines[consumer] = replaced;
        removed[index] = true;
        if hoisted {
            removed[declarations[&id]] = true;
        }
        folded = true;
    }
    if !folded {
        return slots_end;
    }
    out.truncate(slots_start);
    let mut declarations_end = slots_start;
    for (index, (line, removed)) in lines.iter().zip(removed).enumerate() {
        if !removed {
            out.push_str(line);
            if index < body_start {
                declarations_end = out.len();
            }
        }
    }
    declarations_end
}

/// `JET_COPY_TAGS=1`: tag every emitted value clone with its copy fact
/// (`/*copy:<fact>*/`, `unbacked` when no MIR copy fact backs it) for
/// Tools/agent/copy-ratchet.mjs (#4318). Inert when unset.
fn copy_tags_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("JET_COPY_TAGS").is_some_and(|value| value == "1"))
}

/// A Rust type whose values copy, so an owned read names the binding.
fn copy_scalar_type(ty: &str) -> bool {
    matches!(
        ty,
        "bool" | "char" | "f32" | "f64" | "i8" | "i16" | "i32" | "i64" | "i128" | "isize"
            | "u8" | "u16" | "u32" | "u64" | "u128" | "usize"
    )
}

/// Turns block-local value slots into plain `let` bindings. `out[slots_start
/// ..]` holds the function's slot declarations and body. A slot declared at
/// its single definition (`let mut slot: Option<T> = Some(E);`, see
/// `localize_slots`) whose every other mention is a shared read
/// (`slot.as_ref().expect("MIR value")`) is never taken, written through or
/// re-initialized, so it becomes `let slot: T = E;`: an owned read names a
/// Copy scalar directly and clones any other type, and a borrow is `&slot`.
fn unwrap_value_slots(out: &mut String, slots_start: usize) {
    const BORROW: &str = ".as_ref().expect(\"MIR value\")";
    let body = &out[slots_start..];
    // Per slot: (mentions, shared-read mentions), counted in one pass.
    let mut mentions: std::collections::HashMap<u64, (usize, usize)> = std::collections::HashMap::new();
    let mut plain: std::collections::HashMap<u64, bool> = std::collections::HashMap::new();
    let mut definitions: Vec<(u64, bool)> = Vec::new();
    for line in body.split_inclusive('\n') {
        for_each_value_mention(line, |_, at, id| {
            let digits = line[at + "__jet_v_".len()..].bytes().take_while(u8::is_ascii_digit).count();
            let entry = mentions.entry(id).or_default();
            entry.0 += 1;
            if line[at + "__jet_v_".len() + digits..].starts_with(BORROW) {
                entry.1 += 1;
            }
        });
        let Some((indent, id, _, false)) = slot_definition(line) else {
            continue;
        };
        let Some(ty) = line[indent..]
            .strip_prefix(&format!("let mut __jet_v_{id}: Option<"))
            .and_then(|rest| rest.find("> = Some(").map(|end| &rest[..end]))
        else {
            continue;
        };
        definitions.push((id, copy_scalar_type(ty)));
    }
    for (id, copy) in definitions {
        if mentions.get(&id).is_some_and(|(all, borrows)| *all == borrows + 1) {
            plain.insert(id, copy);
        }
    }
    if plain.is_empty() {
        return;
    }
    let mut rebuilt = String::with_capacity(out.len() - slots_start);
    for original in out[slots_start..].split_inclusive('\n') {
        // A plain slot's definition becomes a plain `let`; its expression can
        // itself read other plain slots, so the rewritten line still gets the
        // read replacements below.
        let mut line = original.to_string();
        if let Some((indent, id, expression, false)) = slot_definition(original) {
            if plain.contains_key(&id) {
                let rest = &original[indent + format!("let mut __jet_v_{id}: Option<").len()..];
                let ty = &rest[..rest.find("> = Some(").expect("checked slot definition")];
                line = format!("{}let __jet_v_{id}: {ty} = {expression};\n", &original[..indent]);
            }
        }
        let mut ids = Vec::new();
        for_each_value_mention(&line, |_, _, id| {
            if plain.contains_key(&id) && !ids.contains(&id) {
                ids.push(id);
            }
        });
        if ids.is_empty() {
            rebuilt.push_str(&line);
            continue;
        }
        for id in ids {
            let borrow = format!("__jet_v_{id}.as_ref().expect(\"MIR value\")");
            let read = if plain[&id] {
                format!("__jet_v_{id}")
            } else {
                format!("__jet_v_{id}.clone()")
            };
            line = line
                .replace(&format!("({borrow}).clone()"), &read)
                .replace(&format!("(*{borrow})"), &format!("__jet_v_{id}"))
                .replace(&borrow, &format!("(&__jet_v_{id})"));
        }
        rebuilt.push_str(&line);
    }
    out.truncate(slots_start);
    out.push_str(&rebuilt);
}

/// How `unwrap_slot_options` reads one mention of a function-top `Option`
/// slot.
#[derive(Clone, Copy, PartialEq, Eq)]
enum SlotAccess {
    /// `slot = Some(E);` as a whole statement line.
    Write,
    /// `slot.as_ref().expect(..)` or `slot.as_mut().expect(..)`.
    Borrow,
    /// `slot.take().expect(..)`.
    Take,
}

/// The `Option` slots a function declares at its top (`emit_slots`), with
/// the label their `expect` accesses carry.
const OPTION_SLOT_PREFIXES: [(&str, &str); 2] = [("__jet_l_", "MIR local"), ("__jet_v_", "MIR value")];

/// `let mut <slot>: Option<T> = None;`, or `.. = Some(E);` where
/// `localize_value_slots` declared a slot at its definition, for a numbered
/// local or value slot: the slot, `T`, and the `E` that fills it.
fn option_slot_declaration(line: &str) -> Option<(&str, &str, Option<&str>)> {
    let statement = line.trim_end_matches('\n').trim_start_matches(' ');
    let (name, rest) = statement.strip_prefix("let mut ")?.split_once(": Option<")?;
    if !OPTION_SLOT_PREFIXES.iter().any(|(prefix, _)| numbered_slot_access(name, prefix, "")) {
        return None;
    }
    if let Some(ty) = rest.strip_suffix("> = None;") {
        return Some((name, ty, None));
    }
    let (ty, _) = rest.split_once("> = Some(")?;
    Some((name, ty, Some(option_slot_write_payload(&rest[ty.len() + 1..])?)))
}

/// The payload `E` of a whole-line `<slot> = Some(E);` statement, given the
/// text after the slot name. `None` when `Some(` does not close at the final
/// `)`, or `E` holds a character or label quote this scan does not pair.
fn option_slot_write_payload(rest: &str) -> Option<&str> {
    let payload = rest.trim_end_matches('\n').strip_prefix(" = Some(")?.strip_suffix(");")?;
    let mut depth = 0usize;
    let mut quoted = false;
    let mut escaped = false;
    for byte in payload.bytes() {
        if quoted {
            quoted = escaped || byte != b'"';
            escaped = !escaped && byte == b'\\';
            continue;
        }
        match byte {
            b'"' => quoted = true,
            b'\'' => return None,
            b'(' => depth += 1,
            b')' => depth = depth.checked_sub(1)?,
            _ => {}
        }
    }
    (depth == 0 && !quoted).then_some(payload)
}

/// Unwraps the `Option` slots (`__jet_l_N`, `__jet_v_N`) that every access
/// finds initialized, so the slot holds its value directly (#4566).
/// `out[slots_start..]` holds the declarations and the structured body. A
/// slot qualifies when every body mention is a whole-line `slot = Some(E);`
/// write (or its declaration fills it) or an `as_ref`/`as_mut`/`take`
/// `expect` access outside any closure, and every access has a dominating
/// write: an earlier write whose block (indentation scope) still holds the
/// access, with no `take` after that write and before the access, and no
/// `take` inside a loop entered between them that a later write in the loop
/// body does not refill (a later iteration would find it moved). Rust then
/// proves the initialization the `expect`s asserted. The declaration keeps
/// its place, so drop order is unchanged: `let mut slot: T;` (or
/// `let mut slot: T = E;`), a write `slot = E;`, a borrow `(&slot)` or
/// `(&mut slot)`, and a take `slot`.
fn unwrap_slot_options(out: &mut String, slots_start: usize) {
    let lines: Vec<String> = out[slots_start..].split_inclusive('\n').map(str::to_string).collect();
    let mut declarations: BTreeMap<String, (usize, String)> = BTreeMap::new();
    let mut filled: BTreeSet<String> = BTreeSet::new();
    let mut repeated: BTreeSet<String> = BTreeSet::new();
    for (index, line) in lines.iter().enumerate() {
        if let Some((name, ty, initial)) = option_slot_declaration(line) {
            if declarations.insert(name.to_string(), (index, ty.to_string())).is_some() {
                repeated.insert(name.to_string());
            }
            if initial.is_some() {
                filled.insert(name.to_string());
            }
        }
    }
    declarations.retain(|name, _| !repeated.contains(name));
    if declarations.is_empty() {
        return;
    }
    let indents: Vec<usize> = lines
        .iter()
        .map(|line| {
            let content = line.trim_start_matches(' ');
            if content.trim().is_empty() {
                usize::MAX
            } else {
                line.len() - content.len()
            }
        })
        .collect();
    // `scope_end[i]`: the first later line indented less than line `i` (the
    // end of its block). `body_end[i]`: the first later line indented no
    // deeper (the end of the block line `i` opens). Blank lines close nothing.
    let block_ends = |closes: fn(usize, usize) -> bool| {
        let mut ends = vec![lines.len(); lines.len()];
        let mut open: Vec<usize> = Vec::new();
        for (index, &indent) in indents.iter().enumerate() {
            if indent == usize::MAX {
                continue;
            }
            while let Some(&top) = open.last() {
                if !closes(indent, indents[top]) {
                    break;
                }
                ends[top] = index;
                open.pop();
            }
            open.push(index);
        }
        ends
    };
    let scope_end = block_ends(|indent, opener| indent < opener);
    let body_end = block_ends(|indent, opener| indent <= opener);
    let mut in_closure = vec![false; lines.len()];
    let mut loops: Vec<usize> = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        let content = line.trim();
        if !content.ends_with('{') {
            continue;
        }
        if inside_closure(line, line.trim_end().len() - 1) {
            for flag in &mut in_closure[index + 1..body_end[index]] {
                *flag = true;
            }
        } else if content.ends_with("loop {") || content.starts_with("while ") || content.starts_with("for ") {
            loops.push(index);
        }
    }
    // A declaration that fills its slot is that slot's first write.
    let mut accesses: BTreeMap<&str, Vec<(usize, SlotAccess)>> = declarations
        .iter()
        .filter(|(name, _)| filled.contains(*name))
        .map(|(name, (declared, _))| (name.as_str(), vec![(*declared, SlotAccess::Write)]))
        .collect();
    let mut rejected: BTreeSet<&str> = BTreeSet::new();
    for (index, line) in lines.iter().enumerate() {
        for (prefix, label) in OPTION_SLOT_PREFIXES {
            for (at, _) in line.match_indices(prefix) {
                let end = at + prefix.len() + line[at + prefix.len()..].bytes().take_while(u8::is_ascii_digit).count();
                let joined = line.as_bytes()[..at].last().is_some_and(|byte| is_identifier_byte(*byte))
                    || line.as_bytes().get(end).is_some_and(|byte| is_identifier_byte(*byte));
                if end == at + prefix.len() || joined {
                    continue;
                }
                let Some((name, (declared, _))) = declarations.get_key_value(&line[at..end]) else {
                    continue;
                };
                if index == *declared {
                    continue;
                }
                let rest = &line[end..];
                let expect = format!(".expect(\"{label}\")");
                let access = if in_closure[index] || inside_closure(line, at) {
                    None
                } else if at == indents[index] && option_slot_write_payload(rest).is_some() {
                    Some(SlotAccess::Write)
                } else if [".as_ref()", ".as_mut()"]
                    .iter()
                    .any(|method| rest.strip_prefix(method).is_some_and(|rest| rest.starts_with(&expect)))
                {
                    Some(SlotAccess::Borrow)
                } else if rest.strip_prefix(".take()").is_some_and(|rest| rest.starts_with(&expect)) {
                    Some(SlotAccess::Take)
                } else {
                    None
                };
                match access {
                    Some(access) => accesses.entry(name.as_str()).or_default().push((index, access)),
                    None => {
                        rejected.insert(name.as_str());
                    }
                }
            }
        }
    }
    // `parent[i]`: the line opening the block that holds line `i`.
    // `jumps_before[i]`: how many lines before `i` may leave a block early.
    let mut parent: Vec<Option<usize>> = vec![None; lines.len()];
    let mut enclosing: Vec<usize> = Vec::new();
    let mut jumps_before = vec![0usize; lines.len() + 1];
    for (index, line) in lines.iter().enumerate() {
        let jumps = ["break", "continue", "return"].iter().any(|jump| line.contains(jump));
        jumps_before[index + 1] = jumps_before[index] + usize::from(jumps);
        if indents[index] == usize::MAX {
            continue;
        }
        while enclosing.last().is_some_and(|top| indents[*top] >= indents[index]) {
            enclosing.pop();
        }
        parent[index] = enclosing.last().copied();
        enclosing.push(index);
    }
    // The end of what a write on line `write` initializes for: its own
    // block, widened past each enclosing labeled block (`'label: {`) that
    // always runs the write before control leaves it, which holds when no
    // jump inside that block precedes the write.
    let reach_end = |write: usize| -> usize {
        let mut current = write;
        while let Some(opener) = parent[current] {
            let content = lines[opener].trim();
            let labeled = content.starts_with('\'') && content.ends_with(": {") && !content.ends_with("loop {");
            if !labeled || jumps_before[write] > jumps_before[opener + 1] {
                break;
            }
            current = opener;
        }
        scope_end[current]
    };
    let mut plain: BTreeMap<&str, &str> = BTreeMap::new();
    for (name, (_, ty)) in &declarations {
        if rejected.contains(name.as_str()) {
            continue;
        }
        let rows = accesses.get(name.as_str()).map(Vec::as_slice).unwrap_or(&[]);
        let lines_of = |kind: SlotAccess| -> Vec<usize> {
            rows.iter().filter(|(_, access)| *access == kind).map(|(line, _)| *line).collect()
        };
        let writes = lines_of(SlotAccess::Write);
        let takes = lines_of(SlotAccess::Take);
        // A take inside a loop is refilled when a write in the loop body's
        // own block follows it (the write on the take's own line runs after
        // it) and no `continue` between them skips that write.
        let refilled = |take: usize, header: usize| {
            writes.iter().any(|&refill| {
                refill >= take
                    && refill < body_end[header]
                    && reach_end(refill) == body_end[header]
                    && !lines[take..=refill].iter().any(|line| line.contains("continue"))
            })
        };
        let initialized = rows.iter().filter(|(_, access)| *access != SlotAccess::Write).all(|&(at, _)| {
            let Some(&write) = writes.iter().rev().find(|&&write| write < at && reach_end(write) > at) else {
                return false;
            };
            !takes.iter().any(|&take| take > write && take < at)
                && !loops.iter().any(|&header| {
                    header > write
                        && header < at
                        && body_end[header] > at
                        && takes.iter().any(|&take| {
                            take > header && take < body_end[header] && !refilled(take, header)
                        })
                })
        });
        if initialized {
            plain.insert(name.as_str(), ty.as_str());
        }
    }
    if plain.is_empty() {
        return;
    }
    let mut rebuilt = String::with_capacity(out.len() - slots_start);
    for line in &lines {
        let indent = line.len() - line.trim_start_matches(' ').len();
        let mut line = line.clone();
        if let Some((name, ty, initial)) =
            option_slot_declaration(&line).filter(|(name, _, _)| plain.contains_key(name))
        {
            line = match initial {
                Some(payload) => format!("{}let mut {name}: {ty} = {payload};\n", &line[..indent]),
                None => format!("{}let mut {name}: {ty};\n", &line[..indent]),
            };
        } else if let Some((name, payload)) = plain.keys().find_map(|name| {
            line[indent..]
                .strip_prefix(name)
                .and_then(option_slot_write_payload)
                .map(|payload| (name, payload))
        }) {
            line = format!("{}{name} = {payload};\n", &line[..indent]);
        }
        for (name, label) in plain.keys().flat_map(|name| {
            OPTION_SLOT_PREFIXES
                .iter()
                .filter(move |(prefix, _)| name.starts_with(prefix))
                .map(move |(_, label)| (*name, *label))
        }) {
            if !line.contains(name) {
                continue;
            }
            let borrow = format!("{name}.as_ref().expect(\"{label}\")");
            let borrow_mut = format!("{name}.as_mut().expect(\"{label}\")");
            line = line
                .replace(&format!("({borrow}).clone()"), &format!("{name}.clone()"))
                .replace(&format!("{borrow}.clone()"), &format!("{name}.clone()"))
                .replace(&format!("(*{borrow})"), &format!("({name})"))
                .replace(&format!("(*{borrow_mut})"), &format!("({name})"))
                .replace(&borrow, &format!("(&{name})"))
                .replace(&borrow_mut, &format!("(&mut {name})"))
                .replace(&format!("{name}.take().expect(\"{label}\")"), name);
        }
        rebuilt.push_str(&line);
    }
    out.truncate(slots_start);
    out.push_str(&rebuilt);
}

/// Whether a loop of the function owns its own vector (and acceleration)
/// dispatch arms: only an eligible vector fact does; a rejected fact's loop,
/// and the acceleration facts it carries, are emitted as plain MIR.
fn has_eligible_vector_fact(facts: &MirOptimizationFacts) -> bool {
    facts.vector_facts.iter().any(|fact| fact.decision.is_eligible())
}

/// Whether the function has a scope whose entry or exit emits code. The
/// `Live` scope of every `if` arm (`lower_if`) emits only a comment, so it
/// changes no slot, native shadow or return place.
fn has_effectful_scope(function: &MirFunction) -> bool {
    function.scopes.iter().any(|scope| scope.kind != MirScopeKind::Live)
}

/// The exact `Int` helpers of one arithmetic operator: the owned helper,
/// the raw-word hot macro when one exists, and whether the helper takes the
/// trap location (`exact_int_binary`).
fn exact_int_helpers(op: MirBinaryOp) -> Option<(&'static str, Option<&'static str>, bool)> {
    Some(match op {
        MirBinaryOp::Add => ("jet_int_owned_add", Some("jet_int_add_hot"), false),
        MirBinaryOp::Sub => ("jet_int_owned_sub", Some("jet_int_sub_hot"), false),
        MirBinaryOp::Mul => ("jet_int_owned_mul", Some("jet_int_mul_hot"), false),
        MirBinaryOp::BitAnd => ("jet_int_owned_bit_and", Some("jet_int_bit_and_hot"), false),
        MirBinaryOp::BitOr => ("jet_int_owned_bit_or", Some("jet_int_bit_or_hot"), false),
        MirBinaryOp::BitXor => ("jet_int_owned_bit_xor", Some("jet_int_bit_xor_hot"), false),
        MirBinaryOp::Div => ("jet_int_owned_div", Some("jet_int_div_hot"), true),
        MirBinaryOp::FloorDiv => ("jet_int_owned_floor_div", Some("jet_int_floor_div_hot"), true),
        MirBinaryOp::Mod => ("jet_int_owned_mod", Some("jet_int_mod_hot"), true),
        MirBinaryOp::Rem => ("jet_int_owned_rem", Some("jet_int_rem_hot"), true),
        MirBinaryOp::Pow => ("jet_int_owned_pow", None, true),
        MirBinaryOp::Shl => ("jet_int_owned_shl", Some("jet_int_shl_hot"), true),
        MirBinaryOp::Shr => ("jet_int_owned_shr", Some("jet_int_shr_hot"), true),
        _ => return None,
    })
}
/// #4566 return slot (function-boundary research 4.2, form 2): the hidden
/// last parameter, `&mut Option<T>`, through which a caller's slot holds the
/// result of a return-slot function while its body builds it.
const RETURN_SLOT_PARAMETER: &str = "__jet_return_slot";

/// The smallest result, in bytes, a function builds in its caller's slot.
/// A smaller one returns by value, which Rust places through its own sret.
const RETURN_SLOT_MIN_BYTES: u64 = 256;

/// The body symbol of the return-slot function named `name`. `name` itself
/// stays a by-value wrapper for every reference that is not a direct call.
fn return_slot_symbol(name: &str) -> String {
    format!("{name}__jet_into")
}

/// Bytes of the inline Rust value of `ty` when it has no observable drop:
/// a scalar, or a fixed list of them with a literal length.
fn return_slot_bytes(ty: &MirType) -> Option<u64> {
    match ty.kind() {
        MirTypeKind::Int | MirTypeKind::Float => Some(8),
        MirTypeKind::Float32 | MirTypeKind::Char => Some(4),
        MirTypeKind::Bool => Some(1),
        MirTypeKind::IntN { bits, .. } => Some(u64::from((*bits).max(8) / 8)),
        MirTypeKind::FixedList {
            elem,
            len: MirMeasure::Literal { value, .. },
        } => return_slot_bytes(elem)?.checked_mul(*value),
        _ => None,
    }
}

/// #4566 slice 7 capacity reuse (research 4.3): the payload a reuse write of
/// a return-slot function's place carries until `bind_return_slot` turns it
/// into `jet_reuse_slot(__jet_return_slot)`.
const RETURN_SLOT_REUSE: &str = "__jet_return_reuse";

/// #4566 slice 8: the most values a list keeps inline in its function's
/// frame (`plan_inline_lists`); a longer expected length stays a `Vec`.
const INLINE_LIST_MAX_VALUES: u64 = 64;

/// A String, or a list of scalars or Strings: dropping one releases memory
/// and runs nothing else, so emptying its buffer in place and keeping the
/// capacity is indistinguishable from dropping it and building a fresh one.
fn reusable_buffer_type(ty: &MirType) -> bool {
    match ty.kind() {
        MirTypeKind::String => true,
        MirTypeKind::List(elem) => matches!(
            elem.kind(),
            MirTypeKind::Int
                | MirTypeKind::Float
                | MirTypeKind::Float32
                | MirTypeKind::Bool
                | MirTypeKind::Char
                | MirTypeKind::IntN { .. }
                | MirTypeKind::String
        ),
        _ => false,
    }
}

/// Every place `operation` names: its own place, a captured place, a
/// mutating method receiver, and each write argument's place.
fn operation_named_places(operation: &MirOperation) -> Vec<MirPlaceId> {
    match operation {
        MirOperation::ReadPlace(place)
        | MirOperation::MovePlace { place }
        | MirOperation::InitializeUninit { place }
        | MirOperation::RawAddressOf { place }
        | MirOperation::AddressOf { place, .. }
        | MirOperation::WritePlace { place, .. }
        | MirOperation::ReplacePlace { place, .. } => vec![*place],
        MirOperation::Closure { captures, .. } => captures
            .iter()
            .filter_map(|capture| match capture {
                MirCaptureOperand::Place(place) => Some(*place),
                MirCaptureOperand::Value(_) => None,
            })
            .collect(),
        MirOperation::Semantic(MirSemanticOp::BuiltinMethod {
            receiver_place: Some(place),
            ..
        }) => vec![*place],
        MirOperation::Call { args, .. }
        | MirOperation::CoreCall { args, .. }
        | MirOperation::IndirectCall { args, .. } => args.iter().filter_map(|arg| arg.place).collect(),
        _ => Vec::new(),
    }
}

/// Read arguments with no representation coercion can borrow an exact Int
/// temporary built from a proven native local at the call itself.
fn native_read_call_arg(arg: &MirCallArg) -> bool {
    arg.access == MirAccess::Read
        && arg.place.is_some()
        && !arg.authority_boundary
        && !arg.implicit_clone
        && !arg.shared_auto_clone
        && !arg.widen_fixed_to_list
        && arg.widen_to_union.is_none()
        && arg.box_as_trait.is_none()
        && arg.fn_coercion.is_none()
}

fn native_read_call_args(operation: &MirOperation) -> Option<&[MirCallArg]> {
    match operation {
        MirOperation::Call {
            callee: MirCallee::User(_) | MirCallee::Associated { .. } | MirCallee::Method { .. },
            args, ..
        } => Some(args),
        _ => None,
    }
}

/// Binds the return place `slot` (`__jet_l_N`) of a return-slot function to
/// its caller's slot. `out[slots_start..]` holds the declarations and the
/// body after `unwrap_slot_options`. A local unwrapped there (`let mut slot:
/// T;`) becomes `let mut slot: &mut T;`, and each whole-line write `slot =
/// E;` becomes `slot = __jet_return_slot.insert(E);`: `Option::insert`
/// places `E` in the caller's slot and returns the reference. A write whose
/// `E` reads the local evaluates `E` first, so the old reference is dead
/// before the slot is borrowed again. A write of `RETURN_SLOT_REUSE` (slice
/// 7) becomes `slot = jet_reuse_slot(__jet_return_slot);`, which empties the
/// buffer the caller left in the slot and keeps its capacity. A local that
/// kept its `Option` (`let mut slot: Option<T> = None;`) reborrows the
/// caller's slot, `let slot: &mut Option<T> = __jet_return_slot;`, and its
/// reuse write is `jet_reuse_slot(&mut *slot);`. Every other mention names
/// the value in place, `(*slot)`, a place of the type the mention had.
fn bind_return_slot(out: &mut String, slots_start: usize, slot: &str) {
    let declaration = format!("let mut {slot}: ");
    let assignment = format!("{slot} = ");
    let reuse_write = format!("Some({RETURN_SLOT_REUSE});");
    let in_place = |text: &str| -> String {
        let mut rebuilt = String::with_capacity(text.len() + 8);
        let mut last = 0;
        for at in variable_mentions(text, slot) {
            rebuilt.push_str(&text[last..at]);
            let _ = write!(rebuilt, "(*{slot})");
            last = at + slot.len();
        }
        rebuilt.push_str(&text[last..]);
        rebuilt
    };
    let mut unwrapped = false;
    let mut rebuilt = String::with_capacity(out.len() - slots_start + 64);
    for line in out[slots_start..].split_inclusive('\n') {
        let indent = line.len() - line.trim_start_matches(' ').len();
        let (pad, statement) = (&line[..indent], line[indent..].trim_end_matches('\n'));
        if let Some(rest) = statement.strip_prefix(&declaration) {
            if let Some(ty) = rest.strip_prefix("Option<").and_then(|rest| rest.strip_suffix("> = None;")) {
                let _ = writeln!(rebuilt, "{pad}let {slot}: &mut Option<{ty}> = {RETURN_SLOT_PARAMETER};");
            } else if let Some(ty) = rest.strip_suffix(';').filter(|ty| !ty.contains(" = ")) {
                unwrapped = true;
                let _ = writeln!(rebuilt, "{pad}let mut {slot}: &mut {ty};");
            } else {
                panic!("MIR return place `{slot}` has an unexpected declaration `{statement}`");
            }
            continue;
        }
        if statement.strip_prefix(&assignment) == Some(reuse_write.as_str()) {
            let _ = writeln!(rebuilt, "{pad}jet_reuse_slot(&mut *{slot});");
            continue;
        }
        let payload = statement
            .strip_prefix(&assignment)
            .and_then(|rest| rest.strip_suffix(';'))
            .filter(|_| unwrapped);
        match payload {
            Some(RETURN_SLOT_REUSE) => {
                let _ = writeln!(rebuilt, "{pad}{slot} = jet_reuse_slot({RETURN_SLOT_PARAMETER});");
            }
            Some(payload) if variable_mentions(payload, slot).next().is_some() => {
                let _ = writeln!(
                    rebuilt,
                    "{pad}{{ let __jet_return_value = {}; {slot} = {RETURN_SLOT_PARAMETER}.insert(__jet_return_value); }}",
                    in_place(payload)
                );
            }
            Some(payload) => {
                let _ = writeln!(rebuilt, "{pad}{slot} = {RETURN_SLOT_PARAMETER}.insert({payload});");
            }
            None => rebuilt.push_str(&in_place(line)),
        }
    }
    out.truncate(slots_start);
    out.push_str(&rebuilt);
}

#[cfg(test)]
mod unwrap_value_slot_tests {
    use super::{bind_return_slot, unwrap_slot_options, unwrap_value_slots};

    #[test]
    fn read_only_block_slots_become_plain_lets() {
        let mut out = [
            "    let mut __jet_v_1: Option<String> = None;\n",
            "  let mut __jet_v_2: Option<bool> = Some(f());\n",
            "  if (__jet_v_2.as_ref().expect(\"MIR value\")).clone() {\n",
            "  let mut __jet_v_5: Option<bool> = Some(!(__jet_v_2.as_ref().expect(\"MIR value\")).clone());\n",
            "  m((__jet_v_5.as_ref().expect(\"MIR value\")).clone());\n",
            "   let mut __jet_v_3: Option<String> = Some(g());\n",
            "   h(__jet_v_3.as_ref().expect(\"MIR value\"), (__jet_v_3.as_ref().expect(\"MIR value\")).clone());\n",
            "   let mut __jet_v_4: Option<String> = Some(g());\n",
            "   k(__jet_v_4.take().expect(\"MIR value\"));\n",
            "   __jet_v_1 = Some(g());\n",
            "  }\n",
        ]
        .concat();
        unwrap_value_slots(&mut out, 0);
        let expected = [
            "    let mut __jet_v_1: Option<String> = None;\n",
            "  let __jet_v_2: bool = f();\n",
            "  if __jet_v_2 {\n",
            "  let __jet_v_5: bool = !__jet_v_2;\n",
            "  m(__jet_v_5);\n",
            "   let __jet_v_3: String = g();\n",
            "   h((&__jet_v_3), __jet_v_3.clone());\n",
            "   let mut __jet_v_4: Option<String> = Some(g());\n",
            "   k(__jet_v_4.take().expect(\"MIR value\"));\n",
            "   __jet_v_1 = Some(g());\n",
            "  }\n",
        ]
        .concat();
        assert_eq!(out, expected);
    }

    #[test]
    fn initialized_option_slots_hold_their_values() {
        let local = |id: u32, method: &str| format!("__jet_l_{id}.{method}().expect(\"MIR local\")");
        let mut out = [
            "    let mut __jet_l_1: Option<JetInt> = None;\n".to_string(),
            "    let mut __jet_l_2: Option<Parts> = None;\n".to_string(),
            "    let mut __jet_l_3: Option<Vec<JetInt>> = None;\n".to_string(),
            "    let mut __jet_l_4: Option<JetInt> = None;\n".to_string(),
            "    let mut __jet_v_5: Option<Parts> = None;\n".to_string(),
            "    let mut __jet_l_6: Option<String> = None;\n".to_string(),
            "    __jet_l_1 = Some(zero());\n".to_string(),
            "    __jet_l_3 = Some(vec![]);\n".to_string(),
            "    __jet_l_6 = None;\n".to_string(),
            "    'jet_loop_1: loop {\n".to_string(),
            "        if c {\n".to_string(),
            "            __jet_l_4 = Some(zero());\n".to_string(),
            "        }\n".to_string(),
            format!("        __jet_v_5 = Some(split(&(*{})));\n", local(1, "as_ref")),
            "        __jet_l_2 = Some(__jet_v_5.take().expect(\"MIR value\"));\n".to_string(),
            format!("        __jet_l_1 = Some(add({}, {}));\n", local(1, "take"), local(2, "as_ref")),
            format!("        push({}, {});\n", local(3, "as_mut"), local(4, "as_ref")),
            format!("        {{ drop(({})); () }};\n", local(2, "take")),
            format!("        {{ drop(({})); () }};\n", local(3, "take")),
            "    }\n".to_string(),
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        let expected = [
            "    let mut __jet_l_1: JetInt;\n".to_string(),
            "    let mut __jet_l_2: Parts;\n".to_string(),
            "    let mut __jet_l_3: Option<Vec<JetInt>> = None;\n".to_string(),
            "    let mut __jet_l_4: Option<JetInt> = None;\n".to_string(),
            "    let mut __jet_v_5: Parts;\n".to_string(),
            "    let mut __jet_l_6: Option<String> = None;\n".to_string(),
            "    __jet_l_1 = zero();\n".to_string(),
            "    __jet_l_3 = Some(vec![]);\n".to_string(),
            "    __jet_l_6 = None;\n".to_string(),
            "    'jet_loop_1: loop {\n".to_string(),
            "        if c {\n".to_string(),
            "            __jet_l_4 = Some(zero());\n".to_string(),
            "        }\n".to_string(),
            "        __jet_v_5 = split(&(__jet_l_1));\n".to_string(),
            "        __jet_l_2 = __jet_v_5;\n".to_string(),
            "        __jet_l_1 = add(__jet_l_1, (&__jet_l_2));\n".to_string(),
            format!("        push({}, {});\n", local(3, "as_mut"), local(4, "as_ref")),
            "        { drop((__jet_l_2)); () };\n".to_string(),
            format!("        {{ drop(({})); () }};\n", local(3, "take")),
            "    }\n".to_string(),
        ]
        .concat();
        assert_eq!(out, expected);
    }

    #[test]
    fn labeled_blocks_and_filled_declarations_unwrap() {
        let mut out = [
            "    let mut __jet_l_7: Option<JetInt> = None;\n",
            "    let mut __jet_l_8: Option<JetInt> = None;\n",
            "    'jet_block_1: {\n",
            "        __jet_l_7 = Some(one());\n",
            "        if d {\n",
            "            break 'jet_block_1;\n",
            "        }\n",
            "        __jet_l_8 = Some(one());\n",
            "        break 'jet_block_1;\n",
            "    }\n",
            "    f(__jet_l_7.as_ref().expect(\"MIR local\"), __jet_l_8.as_ref().expect(\"MIR local\"));\n",
            "    let mut __jet_v_9: Option<String> = Some(g(\"(\"));\n",
            "    k(__jet_v_9.take().expect(\"MIR value\"));\n",
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        let expected = [
            "    let mut __jet_l_7: JetInt;\n",
            "    let mut __jet_l_8: Option<JetInt> = None;\n",
            "    'jet_block_1: {\n",
            "        __jet_l_7 = one();\n",
            "        if d {\n",
            "            break 'jet_block_1;\n",
            "        }\n",
            "        __jet_l_8 = Some(one());\n",
            "        break 'jet_block_1;\n",
            "    }\n",
            "    f((&__jet_l_7), __jet_l_8.as_ref().expect(\"MIR local\"));\n",
            "    let mut __jet_v_9: String = g(\"(\");\n",
            "    k(__jet_v_9);\n",
        ]
        .concat();
        assert_eq!(out, expected);
    }

    #[test]
    fn return_places_live_in_the_caller_slot() {
        let mut out = [
            "    let mut __jet_l_1: Option<JetInt> = None;\n",
            "    let mut __jet_l_3: Option<[JetInt; 4]> = None;\n",
            "    __jet_l_3 = Some([a(), a(), a(), a()]);\n",
            "    __jet_l_1 = Some(z());\n",
            "    'jet_loop_1: loop {\n",
            "        set(&mut (*__jet_l_3.as_mut().expect(\"MIR local\")), 0);\n",
            "        __jet_l_3 = Some(swap((*__jet_l_3.as_ref().expect(\"MIR local\"))[1]));\n",
            "        break 'jet_loop_1;\n",
            "    }\n",
            "    return;\n",
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        bind_return_slot(&mut out, 0, "__jet_l_3");
        let expected = [
            "    let mut __jet_l_1: JetInt;\n",
            "    let mut __jet_l_3: &mut [JetInt; 4];\n",
            "    __jet_l_3 = __jet_return_slot.insert([a(), a(), a(), a()]);\n",
            "    __jet_l_1 = z();\n",
            "    'jet_loop_1: loop {\n",
            "        set(&mut ((*__jet_l_3)), 0);\n",
            "        { let __jet_return_value = swap(((*__jet_l_3))[1]); __jet_l_3 = __jet_return_slot.insert(__jet_return_value); }\n",
            "        break 'jet_loop_1;\n",
            "    }\n",
            "    return;\n",
        ]
        .concat();
        assert_eq!(out, expected);
        let mut out = [
            "    let mut __jet_l_4: Option<[JetInt; 2]> = None;\n",
            "    if c {\n",
            "        __jet_l_4 = Some(x());\n",
            "    } else {\n",
            "        __jet_l_4 = Some(y());\n",
            "    }\n",
            "    use_it(__jet_l_4.as_ref().expect(\"MIR local\"), __jet_l_40);\n",
            "    return;\n",
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        bind_return_slot(&mut out, 0, "__jet_l_4");
        let expected = [
            "    let __jet_l_4: &mut Option<[JetInt; 2]> = __jet_return_slot;\n",
            "    if c {\n",
            "        (*__jet_l_4) = Some(x());\n",
            "    } else {\n",
            "        (*__jet_l_4) = Some(y());\n",
            "    }\n",
            "    use_it((*__jet_l_4).as_ref().expect(\"MIR local\"), __jet_l_40);\n",
            "    return;\n",
        ]
        .concat();
        assert_eq!(out, expected);
    }

    #[test]
    fn reuse_writes_empty_the_caller_buffer() {
        let mut out = [
            "    let mut __jet_l_2: Option<Vec<JetInt>> = None;\n",
            "    __jet_l_2 = Some(__jet_return_reuse);\n",
            "    jet_list_push(__jet_l_2.as_mut().expect(\"MIR local\"), one());\n",
            "    return;\n",
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        bind_return_slot(&mut out, 0, "__jet_l_2");
        let expected = [
            "    let mut __jet_l_2: &mut Vec<JetInt>;\n",
            "    __jet_l_2 = jet_reuse_slot(__jet_return_slot);\n",
            "    jet_list_push((&mut (*__jet_l_2)), one());\n",
            "    return;\n",
        ]
        .concat();
        assert_eq!(out, expected);
        let mut out = [
            "    let mut __jet_l_5: Option<String> = None;\n",
            "    if c {\n",
            "        __jet_l_5 = Some(__jet_return_reuse);\n",
            "    } else {\n",
            "        __jet_l_5 = Some(x());\n",
            "    }\n",
            "    use_it(__jet_l_5.as_ref().expect(\"MIR local\"));\n",
            "    return;\n",
        ]
        .concat();
        unwrap_slot_options(&mut out, 0);
        bind_return_slot(&mut out, 0, "__jet_l_5");
        let expected = [
            "    let __jet_l_5: &mut Option<String> = __jet_return_slot;\n",
            "    if c {\n",
            "        jet_reuse_slot(&mut *__jet_l_5);\n",
            "    } else {\n",
            "        (*__jet_l_5) = Some(x());\n",
            "    }\n",
            "    use_it((*__jet_l_5).as_ref().expect(\"MIR local\"));\n",
            "    return;\n",
        ]
        .concat();
        assert_eq!(out, expected);
    }
}

#[cfg(test)]
mod localize_slot_tests {
    use super::localize_slots;
    use std::collections::BTreeMap;

    #[test]
    fn block_local_slots_are_declared_at_their_definition() {
        let declarations = [
            "    let mut __jet_l_1: Option<Expr> = None;\n",
            "    let mut __jet_l_2: Option<Expr> = None;\n",
            "    let mut __jet_l_3: Option<Expr> = None;\n",
            "    let mut __jet_l_4: Option<&Expr> = None;\n",
            "    let mut __jet_l_5: Option<Expr> = None;\n",
            "    let mut __jet_l_6: Option<Expr> = None;\n",
        ]
        .concat();
        let body = [
            "    if c {\n",
            "        __jet_l_1 = Some(f());\n",
            "        g(__jet_l_1.as_ref().expect(\"MIR local\"));\n",
            "        __jet_l_2 = Some(f());\n",
            "    }\n",
            "    g(__jet_l_2.as_ref().expect(\"MIR local\"));\n",
            "    if c {\n",
            "        __jet_l_3 = Some(f());\n",
            "        __jet_l_4 = Some(__jet_l_3.as_ref().expect(\"MIR local\"));\n",
            "        __jet_l_5 = Some(f()); h(__jet_l_5.take());\n",
            "    }\n",
        ]
        .concat();
        let mut out = format!("{declarations}{body}");
        let candidates: BTreeMap<u64, String> =
            [1, 2, 3, 5, 6].into_iter().map(|id| (id, "Expr".to_string())).collect();
        let end = localize_slots(&mut out, 0, declarations.len(), "__jet_l_", &candidates);
        let expected = [
            "    let mut __jet_l_2: Option<Expr> = None;\n",
            "    let mut __jet_l_3: Option<Expr> = None;\n",
            "    let mut __jet_l_4: Option<&Expr> = None;\n",
            "    let mut __jet_l_5: Option<Expr> = None;\n",
            "    if c {\n",
            "        let mut __jet_l_1: Option<Expr> = Some(f());\n",
            "        g(__jet_l_1.as_ref().expect(\"MIR local\"));\n",
            "        __jet_l_2 = Some(f());\n",
            "    }\n",
            "    g(__jet_l_2.as_ref().expect(\"MIR local\"));\n",
            "    if c {\n",
            "        __jet_l_3 = Some(f());\n",
            "        __jet_l_4 = Some(__jet_l_3.as_ref().expect(\"MIR local\"));\n",
            "        __jet_l_5 = Some(f()); h(__jet_l_5.take());\n",
            "    }\n",
        ]
        .concat();
        assert_eq!(out, expected);
        assert_eq!(end, 4 * "    let mut __jet_l_2: Option<Expr> = None;\n".len() + 1);
    }
}

/// Slot name prefixes whose names are numbered from a MIR id.
const NUMBERED_SLOT_PREFIXES: [&str; 3] = ["__jet_v_", "__jet_l_", "__jet_pm_"];

/// The byte length of the numbered slot name (`__jet_v_N`, `__jet_l_N`,
/// `__jet_pm_N`) starting at `at` when its digits end the identifier, else 0.
fn numbered_slot_len(text: &[u8], at: usize) -> usize {
    for prefix in NUMBERED_SLOT_PREFIXES {
        if !text[at..].starts_with(prefix.as_bytes()) {
            continue;
        }
        let digits_start = at + prefix.len();
        let digits = text[digits_start..].iter().take_while(|byte| byte.is_ascii_digit()).count();
        let end = digits_start + digits;
        if digits > 0 && !text.get(end).copied().is_some_and(is_identifier_byte) {
            return end - at;
        }
    }
    0
}

/// Deletes the slot declarations nothing reads. `out[start..]` holds the
/// function's slot declarations and body. A line `let mut slot: Option<T> =
/// None;` (any indent, not under an attribute) whose numbered slot name is
/// mentioned nowhere else in that text declares storage no statement uses:
/// it only holds `None`, so its drop is a no-op and removing it changes
/// nothing but the frame size. Mentions are counted over the raw text,
/// string and comment text included, so a doubtful slot is kept.
fn drop_unmentioned_slots(out: &mut String, start: usize) {
    let body = &out[start..];
    let bytes = body.as_bytes();
    let mut mentions: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    let mut index = 0;
    while index < bytes.len() {
        let joined = index > 0 && is_identifier_byte(bytes[index - 1]);
        let len = if bytes[index] == b'_' && !joined { numbered_slot_len(bytes, index) } else { 0 };
        if len == 0 {
            index += 1;
            continue;
        }
        *mentions.entry(&body[index..index + len]).or_default() += 1;
        index += len;
    }
    let unused = |line: &str| -> bool {
        let content = line.trim_end_matches('\n').trim_start_matches(' ');
        let Some(rest) = content.strip_prefix("let mut ") else {
            return false;
        };
        let len = numbered_slot_len(rest.as_bytes(), 0);
        len > 0
            && rest[len..].starts_with(": Option<")
            && rest.ends_with("> = None;")
            && mentions.get(&rest[..len]) == Some(&1)
    };
    let mut kept = String::with_capacity(body.len());
    let mut previous: Option<&str> = None;
    let mut removed = false;
    for line in body.split_inclusive('\n') {
        let attributed = previous.is_some_and(|line| line.trim_start_matches(' ').starts_with("#["));
        if !attributed && unused(line) {
            removed = true;
        } else {
            kept.push_str(line);
        }
        previous = Some(line);
    }
    if removed {
        out.truncate(start);
        out.push_str(&kept);
    }
}

